package gimhub;

public interface APISerializable {
    Object serialize();

    default APISerializable diff(APISerializable newer) {
        return this;
    }

    default boolean isBaselineProperty() {
        return false;
    }
}

package gimhub;

import javax.inject.Inject;
import javax.inject.Singleton;

@Singleton
public class ApiUrlBuilder {
    @Inject
    private GimHubConfig config;

    @Inject
    private HttpRequestService httpRequestService;

    public String getUpdateGroupMemberUrl() {
        String baseUrl = httpRequestService.getBaseUrl();
        String groupName = getGroupName();

        if (baseUrl == null || groupName == null) return null;

        return String.format("%s/api/group/%s/update-group-member", baseUrl, groupName);
    }

    public String getMembershipCheckUrl(String playerName) {
        String baseUrl = httpRequestService.getBaseUrl();
        String groupName = getGroupName();

        if (baseUrl == null || groupName == null) return null;

        return String.format("%s/api/group/%s/am-i-in-group?member_name=%s", baseUrl, groupName, playerName);
    }

    private String getGroupName() {
        String groupName = config.groupName().trim();

        return groupName.isEmpty() ? null : groupName;
    }
}

package gimhub;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.io.IOException;
import java.io.Reader;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.Objects;
import java.util.Set;
import java.util.concurrent.CompletableFuture;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.NonNull;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;

@Slf4j
@Singleton
public class CollectionLogItemResolver {
    private static final String ITEM_CACHE_BASE_URL = "https://static.runelite.net/cache/item/";

    private final Map<String, Integer> itemIdentifierByName = Collections.synchronizedMap(new HashMap<>(16384));

    @Inject
    private OkHttpClient okHttpClient;

    @Inject
    private Gson gson;

    @Inject
    protected void initialize() {
        queryNamesByIdentifier()
                .thenAcceptBothAsync(queryNotedItemIdentifiers(), this::populate)
                .exceptionally(exception -> {
                    log.error("Failed to initialize collection log item names", exception);
                    return null;
                });
    }

    @Nullable public Integer findItemIdentifier(@NonNull String name) {
        return itemIdentifierByName.get(name);
    }

    protected void populate(Map<Integer, String> namesByIdentifier, Set<Integer> notedItemIdentifiers) {
        namesByIdentifier.entrySet().stream()
                .sorted(Map.Entry.comparingByKey())
                .filter(entry -> !notedItemIdentifiers.contains(entry.getKey()))
                .forEach(entry -> itemIdentifierByName.putIfAbsent(entry.getValue(), entry.getKey()));

        log.debug("Initialized collection log item names with {} entries", itemIdentifierByName.size());
    }

    protected CompletableFuture<Map<Integer, String>> queryNamesByIdentifier() {
        return queryCache("names.json", new TypeToken<Map<Integer, String>>() {});
    }

    protected CompletableFuture<Set<Integer>> queryNotedItemIdentifiers() {
        return queryCache("notes.json", new TypeToken<Map<Integer, Integer>>() {})
                .thenApply(Map::keySet);
    }

    protected <Type> CompletableFuture<Type> queryCache(String fileName, TypeToken<Type> typeToken) {
        CompletableFuture<Type> future = new CompletableFuture<>();
        Request request = new Request.Builder()
                .url(String.format("%s%s", ITEM_CACHE_BASE_URL, fileName))
                .build();

        okHttpClient.newCall(request).enqueue(new Callback() {
            @Override
            public void onFailure(@NonNull Call call, @NonNull IOException exception) {
                future.completeExceptionally(exception);
            }

            @Override
            public void onResponse(@NonNull Call call, @NonNull Response response) {
                try (Response closeableResponse = response;
                        Reader reader =
                                Objects.requireNonNull(closeableResponse.body()).charStream()) {
                    future.complete(gson.fromJson(reader, typeToken.getType()));
                } catch (Exception exception) {
                    future.completeExceptionally(exception);
                }
            }
        });

        return future;
    }
}

package gimhub;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Iterator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.MenuAction;
import net.runelite.api.ScriptID;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.ScriptPostFired;
import net.runelite.api.events.ScriptPreFired;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarClientID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStack;
import net.runelite.client.plugins.loottracker.LootReceived;
import net.runelite.client.util.Text;
import net.runelite.http.api.loottracker.LootRecordType;

@Slf4j
public class CollectionLogManager {
    private static final int COLLECTION_DELAYED_TRANSMIT_SCRIPT = 4100;
    private static final int COLLECTION_LOG_SETUP_SCRIPT = 7797;
    private static final int COLLECTION_INITIALIZATION_SCRIPT = 2240;
    private static final int COLLECTION_LOG_TRANSMIT_BUFFER_TICKS = 2;
    private static final int COLLECTION_LOG_NOTIFICATION_PREFIX_LENGTH = "New item:".length();
    private static final Pattern NEW_ITEM_MESSAGE_PATTERN =
            Pattern.compile("New item added to your collection log: (?<itemName>(.*))");
    private static final Set<String> IGNORED_NOTIFICATION_ITEMS = Set.of(
            "Chompy bird hat",
            "Decorative sword",
            "Decorative armour",
            "Decorative helm",
            "Decorative shield",
            "Castlewars hood",
            "Castlewars cloak",
            "Rum",
            "Ancient page",
            "Graceful hood",
            "Graceful cape",
            "Graceful top",
            "Graceful legs",
            "Graceful gloves",
            "Graceful boots",
            "Mysterious page",
            "Decorative boots",
            "Decorative full helm",
            "Medallion fragment",
            "Crawling hand");

    private static final int UNLOCK_MATCH_TICKS = 10;
    private final List<PendingUpdate> pendingUpdates = new ArrayList<>();
    private final Map<Integer, Integer> recentDropTicks = new HashMap<>();
    private final Set<Integer> notifiedItems = new HashSet<>();
    private int currentTick;

    private static class PendingUpdate {
        private final String type;
        private final Map<Integer, Integer> items;
        private int tick;
        private boolean awaitingChambersLoot;
        private Integer totalObtained;

        private PendingUpdate(String type, Map<Integer, Integer> items, int tick) {
            this.type = type;
            this.items = new LinkedHashMap<>(items);
            this.tick = tick;
        }
    }

    private boolean automaticCollectionLogRetrieval = false;
    private PendingUpdate automaticScan;
    private boolean collectionLogNotificationStarted = false;
    private int collectionLogTransmitTick = -1;

    public synchronized void storeCollectionLogItem(int itemIdentifier, int quantity) {
        if (quantity < 0) return;
        if (!pendingUpdates.isEmpty()) {
            PendingUpdate last = pendingUpdates.get(pendingUpdates.size() - 1);
            if (last.type.equals("scan") && last.totalObtained == null) {
                last.items.put(itemIdentifier, quantity);
                return;
            }
        }
        pendingUpdates.add(new PendingUpdate("scan", Map.of(itemIdentifier, quantity), currentTick));
    }

    public synchronized void clearCollectionLogItems() {
        pendingUpdates.removeIf(update -> update.type.equals("scan"));
        automaticScan = null;
        automaticCollectionLogRetrieval = false;
        collectionLogTransmitTick = -1;
    }

    public synchronized void flatten(Map<String, APISerializable> flat) {
        if (automaticCollectionLogRetrieval) return;

        List<CollectionLogUpdates.Update> ready = new ArrayList<>();
        Iterator<PendingUpdate> iterator = pendingUpdates.iterator();
        while (iterator.hasNext()) {
            PendingUpdate update = iterator.next();
            if (update.awaitingChambersLoot
                    || (update.type.equals("unlock") && currentTick <= update.tick + UNLOCK_MATCH_TICKS)) break;
            if (!update.items.isEmpty() || update.totalObtained != null) {
                ready.add(new CollectionLogUpdates.Update(update.type, update.items, update.totalObtained));
            }
            iterator.remove();
        }
        if (!ready.isEmpty()) flat.put("collection_log_updates", new CollectionLogUpdates(ready));
    }

    public synchronized void onLootReceived(Client client, LootReceived event, ItemManager itemManager) {
        if (event.getType() != LootRecordType.NPC
                && event.getType() != LootRecordType.EVENT
                && event.getType() != LootRecordType.PICKPOCKET) return;
        if (event.getName().equals("Loot Chest")) return;
        currentTick = client.getTickCount();

        Map<Integer, Integer> items = new LinkedHashMap<>();
        for (ItemStack item : event.getItems()) {
            int identifier = itemManager.canonicalize(item.getId());
            items.merge(identifier, item.getQuantity(), Integer::sum);
            recentDropTicks.put(identifier, currentTick);
        }
        boolean chambersLoot =
                event.getType() == LootRecordType.EVENT && event.getName().equals("Chambers of Xeric");
        items.keySet().removeIf(itemIdentifier -> reconcileUnlock(itemIdentifier, chambersLoot));
        if (chambersLoot) {
            for (PendingUpdate update : pendingUpdates) {
                if (update.awaitingChambersLoot) {
                    update.awaitingChambersLoot = false;
                    update.tick = -UNLOCK_MATCH_TICKS - 1;
                }
            }
        }
        if (!items.isEmpty()) pendingUpdates.add(new PendingUpdate("drop", items, currentTick));
    }

    /** Returns whether a scan after the matching unlock already includes this acquisition. */
    protected boolean reconcileUnlock(int itemIdentifier, boolean chambersLoot) {
        boolean matchedUnlock = false;
        boolean alreadyScanned = false;
        Iterator<PendingUpdate> iterator = pendingUpdates.iterator();
        while (iterator.hasNext()) {
            PendingUpdate update = iterator.next();
            if (update.type.equals("unlock")
                    && update.items.containsKey(itemIdentifier)
                    && (update.awaitingChambersLoot ? chambersLoot : currentTick <= update.tick + UNLOCK_MATCH_TICKS)) {
                matchedUnlock = true;
                iterator.remove();
            } else if (matchedUnlock
                    && update.type.equals("scan")
                    && update.items.getOrDefault(itemIdentifier, 0) > 0) {
                alreadyScanned = true;
            }
        }
        return alreadyScanned;
    }

    public void onGameStateChanged(GameStateChanged event) {
        GameState gameState = event.getGameState();

        if (gameState != GameState.HOPPING && gameState != GameState.LOGGED_IN) {
            resetTransientState();
        }
    }

    protected synchronized void resetTransientState() {
        automaticCollectionLogRetrieval = false;
        automaticScan = null;
        collectionLogNotificationStarted = false;
        collectionLogTransmitTick = -1;
        pendingUpdates.stream()
                .filter(update -> update.type.equals("unlock"))
                .forEach(update -> update.tick = -UNLOCK_MATCH_TICKS - 1);
        recentDropTicks.clear();
    }

    public synchronized void onGameTick(Client client) {
        currentTick = client.getTickCount();
        recentDropTicks.values().removeIf(tick -> currentTick > tick + UNLOCK_MATCH_TICKS);
        if (collectionLogTransmitTick == -1
                || collectionLogTransmitTick + COLLECTION_LOG_TRANSMIT_BUFFER_TICKS >= client.getTickCount()) {
            return;
        }

        if (automaticScan != null
                && pendingUpdates.get(pendingUpdates.size() - 1) == automaticScan
                && client.getVarpValue(VarPlayerID.COLLECTION_COUNT_MAX) > 0
                && automaticScan.items.values().stream()
                                .filter(quantity -> quantity > 0)
                                .count()
                        == client.getVarpValue(VarPlayerID.COLLECTION_COUNT)) {
            automaticScan.totalObtained = client.getVarpValue(VarPlayerID.COLLECTION_COUNT);
            log.debug(
                    "Collection log scan ready: {} transmitted items, game total {}.",
                    automaticScan.items.size(),
                    automaticScan.totalObtained);
        }

        automaticScan = null;
        collectionLogTransmitTick = -1;
        automaticCollectionLogRetrieval = false;
    }

    public void onScriptPreFired(
            Client client, ScriptPreFired event, CollectionLogItemResolver collectionLogItemResolver) {
        currentTick = client.getTickCount();
        if (event.getScriptId() == COLLECTION_DELAYED_TRANSMIT_SCRIPT) {
            if (isAdventureLogOpen(client)) {
                return;
            }

            collectionLogTransmitTick = client.getTickCount();

            Object[] arguments = event.getScriptEvent().getArguments();
            int itemIdentifier = (int) arguments[1];
            int quantity = (int) arguments[2];

            storeCollectionLogItem(itemIdentifier, quantity);
            return;
        }

        if (event.getScriptId() == ScriptID.NOTIFICATION_START) {
            collectionLogNotificationStarted = true;
            return;
        }

        if (event.getScriptId() != ScriptID.NOTIFICATION_DELAY) {
            return;
        }

        String title = client.getVarcStrValue(VarClientID.NOTIFICATION_TITLE);
        boolean notificationStarted = collectionLogNotificationStarted;
        collectionLogNotificationStarted = false;

        if (!notificationStarted || !"Collection log".equalsIgnoreCase(title)) {
            return;
        }

        String message = sanitize(client.getVarcStrValue(VarClientID.NOTIFICATION_MAIN));
        handleNewCollectionLogItem(
                client,
                message.substring(COLLECTION_LOG_NOTIFICATION_PREFIX_LENGTH).trim(),
                collectionLogItemResolver);
    }

    public synchronized void onScriptPostFired(Client client, ScriptPostFired event) {
        if (event.getScriptId() != COLLECTION_LOG_SETUP_SCRIPT) {
            return;
        }

        if (isAdventureLogOpen(client)) {
            clearCollectionLogItems();
            return;
        }

        if (automaticCollectionLogRetrieval) {
            return;
        }

        automaticCollectionLogRetrieval = true;
        automaticScan = new PendingUpdate("scan", Map.of(), client.getTickCount());
        pendingUpdates.add(automaticScan);
        collectionLogTransmitTick = client.getTickCount();
        client.menuAction(-1, InterfaceID.Collection.SEARCH_TOGGLE, MenuAction.CC_OP, 1, -1, "Search", null);
        client.runScript(COLLECTION_INITIALIZATION_SCRIPT);
    }

    public void onVarbitChanged(Client client, VarbitChanged event) {
        if (event.getVarbitId() == VarbitID.COLLECTION_POH_HOST_BOOK_OPEN && isAdventureLogOpen(client)) {
            log.debug("Collection log opened from adventure log, clearing stored items to avoid incorrect updates.");
            clearCollectionLogItems();
        }
    }

    public void onChatMessage(Client client, ChatMessage event, CollectionLogItemResolver collectionLogItemResolver) {
        currentTick = client.getTickCount();
        if (event.getType() != ChatMessageType.GAMEMESSAGE
                || client.getVarbitValue(VarbitID.OPTION_COLLECTION_NEW_ITEM) != 1) {
            return;
        }

        Matcher matcher = NEW_ITEM_MESSAGE_PATTERN.matcher(sanitize(event.getMessage()));
        if (matcher.find()) {
            handleNewCollectionLogItem(client, matcher.group("itemName"), collectionLogItemResolver);
        }
    }

    protected synchronized void handleNewCollectionLogItem(
            Client client, String itemName, CollectionLogItemResolver collectionLogItemResolver) {
        if (IGNORED_NOTIFICATION_ITEMS.contains(itemName)) {
            log.debug("Ignoring collection log item with non-unique name: {}", itemName);
            return;
        }

        Integer itemIdentifier = collectionLogItemResolver.findItemIdentifier(itemName);
        if (itemIdentifier == null) {
            log.debug("Failed to find item ID for: {}", itemName);
            return;
        }

        if (!notifiedItems.add(itemIdentifier)) return;
        if (recentDropTicks.containsKey(itemIdentifier)
                && currentTick <= recentDropTicks.get(itemIdentifier) + UNLOCK_MATCH_TICKS) return;
        PendingUpdate update = new PendingUpdate("unlock", Map.of(itemIdentifier, 1), currentTick);
        update.awaitingChambersLoot = client.getVarbitValue(VarbitID.RAIDS_CLIENT_INDUNGEON) == 1;
        pendingUpdates.add(update);
    }

    protected boolean isAdventureLogOpen(Client client) {
        return client.getVarbitValue(VarbitID.COLLECTION_POH_HOST_BOOK_OPEN) == 1;
    }

    protected String sanitize(String value) {
        if (value == null || value.isEmpty()) return "";
        return Text.removeTags(value.replace("<br>", "\n"))
                .replace('\u00A0', ' ')
                .trim();
    }
}

package gimhub;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;

public class CollectionLogUpdates implements APISerializable {
    private final List<Update> updates;

    public static class Update {
        private final String type;
        private final Map<Integer, Integer> items;
        private final Integer totalObtained;

        public Update(String type, Map<Integer, Integer> items) {
            this(type, items, null);
        }

        public Update(String type, Map<Integer, Integer> items, Integer totalObtained) {
            this.type = type;
            this.totalObtained = totalObtained;
            this.items = new LinkedHashMap<>(items);
        }

        private Map<String, Object> serialize() {
            Map<String, Object> serialized = new LinkedHashMap<>(Map.of(
                    "type",
                    type,
                    "items",
                    items.entrySet().stream()
                            .map(item -> Map.of("item_id", item.getKey(), "quantity", item.getValue()))
                            .collect(Collectors.toList())));
            if (totalObtained != null) serialized.put("total_obtained", totalObtained);
            return serialized;
        }
    }

    public CollectionLogUpdates(List<Update> updates) {
        this.updates = new ArrayList<>(updates);
    }

    public static APISerializable combine(APISerializable older, APISerializable newer) {
        List<Update> combined = new ArrayList<>(((CollectionLogUpdates) older).updates);
        combined.addAll(((CollectionLogUpdates) newer).updates);
        return new CollectionLogUpdates(combined);
    }

    @Override
    public Object serialize() {
        return updates.stream().map(Update::serialize).collect(Collectors.toList());
    }
}

package gimhub;

import gimhub.achievement.AchievementRepository;
import gimhub.activity.ActivityRepository;
import gimhub.activity.LeagueMode;
import gimhub.items.ItemRepository;
import gimhub.states.LeagueModeState;
import gimhub.states.PlayerNameState;
import gimhub.states.TimezoneState;
import java.util.HashMap;
import java.util.Map;
import java.util.Map.Entry;
import java.util.concurrent.atomic.AtomicReference;
import java.util.stream.Collectors;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.client.config.RuneScapeProfileType;

@Slf4j
@Singleton
public class DataManager {
    // Managed by the Client thread

    private PlayerState state = null;

    @Getter
    private volatile String activePlayerName;

    private FlatState flatMostRecent = null;

    // Shared by both threads

    private final AtomicReference<FlatState> flatRef = new AtomicReference<>();

    @Inject
    private HttpRequestService httpRequestService;

    @Inject
    private GimHubConfig config;

    @Inject
    private ApiUrlBuilder apiUrlBuilder;

    private boolean isMemberInGroup = false;
    private int skipNextNAttempts = 0;

    /** Our tracked state of the player: their stats, items, location, etc. */
    public static class PlayerState {
        public final String ownedPlayer;
        public final RuneScapeProfileType ownedProfileType;
        public final long accountHash;
        public final ActivityRepository activityRepository;
        public final ItemRepository itemRepository;
        public final AchievementRepository achievementRepository;
        public final CollectionLogManager collectionLogManager;

        private FlatState flatten() {
            Map<String, APISerializable> flat = new HashMap<>();

            flat.put("name", new PlayerNameState(ownedPlayer));
            flat.put("league_mode", new LeagueModeState(ownedProfileType));
            flat.put("timezone", new TimezoneState());
            activityRepository.flatten(flat);
            itemRepository.flatten(flat);
            achievementRepository.flatten(flat);
            collectionLogManager.flatten(flat);

            flat.entrySet().removeIf(e -> e.getValue() == null);

            return new FlatState(ownedPlayer, ownedProfileType, flat);
        }

        PlayerState(String ownedPlayer, RuneScapeProfileType ownedProfileType, long accountHash) {
            this.accountHash = accountHash;
            this.ownedPlayer = ownedPlayer;
            this.ownedProfileType = ownedProfileType;
            this.activityRepository = new ActivityRepository();
            this.itemRepository = new ItemRepository();
            this.achievementRepository = new AchievementRepository();
            this.collectionLogManager = new CollectionLogManager();
        }
    }

    /** PlayerState flattened but not yet serialized, in a form that allows easier diffing by key-value-pairs. */
    private static class FlatState {
        @Getter
        private final String ownedPlayer;

        private final RuneScapeProfileType ownedProfileType;
        private final Map<String, APISerializable> fields;

        private boolean hasDifferentOwner(FlatState other) {
            return !ownedPlayer.equals(other.ownedPlayer) || ownedProfileType != other.ownedProfileType;
        }

        public static FlatState combineWithPriority(FlatState priority, FlatState defaults) {
            if (priority.hasDifferentOwner(defaults)) {
                return new FlatState(priority.ownedPlayer, priority.ownedProfileType, new HashMap<>(priority.fields));
            }

            Map<String, APISerializable> mergedFields = new HashMap<>(defaults.fields);
            priority.fields.forEach((key, value) -> {
                if (key.equals("collection_log_updates")) {
                    mergedFields.merge(key, value, CollectionLogUpdates::combine);
                } else {
                    mergedFields.put(key, value);
                }
            });

            return new FlatState(priority.ownedPlayer, priority.ownedProfileType, mergedFields);
        }

        public static FlatState diffKeepChangedFields(FlatState newer, FlatState older) {
            if (newer.hasDifferentOwner(older)) {
                return new FlatState(newer.ownedPlayer, newer.ownedProfileType, new HashMap<>(newer.fields));
            }

            Map<String, APISerializable> fieldsThatChanged = new HashMap<>(newer.fields);

            for (Entry<String, APISerializable> entry : older.fields.entrySet()) {
                APISerializable newerValue = fieldsThatChanged.get(entry.getKey());
                APISerializable olderValue = entry.getValue();

                if (olderValue.isBaselineProperty()) {
                    continue;
                }

                if (newerValue != null && newerValue.equals(olderValue)) {
                    fieldsThatChanged.remove(entry.getKey());
                } else if (entry.getKey().endsWith("_partial")) {
                    // Send incremental updates to the server when we don't know the full state.
                    fieldsThatChanged.put(entry.getKey(), entry.getValue().diff(newer.fields.get(entry.getKey())));
                }
            }

            return new FlatState(newer.ownedPlayer, newer.ownedProfileType, fieldsThatChanged);
        }

        public boolean hasChangesBeyondBaseline() {
            return fields.values().stream().anyMatch(field -> !field.isBaselineProperty());
        }

        public Map<String, Object> serialize() {
            return fields.entrySet().stream()
                    .collect(Collectors.toMap(Entry::getKey, e -> e.getValue().serialize()));
        }

        FlatState(String player, RuneScapeProfileType ownedProfileType, Map<String, APISerializable> fields) {
            this.ownedPlayer = player;
            this.ownedProfileType = ownedProfileType;
            this.fields = fields;
        }
    }

    /**
     * Call from Client thread. Get the PlayerState to then write updates to. Checks the passed client to see if the
     * player changes and is valid. If the player name or profile changes, then the state is reset before being
     * returned.
     *
     * @return The current valid PlayerState, or null if the Player is invalid.
     */
    @Nullable public PlayerState getMaybeResetState(Client client) {
        final RuneScapeProfileType profileType = RuneScapeProfileType.getCurrent(client);
        final boolean isValidPlayerLoggedIn = client.getGameState() == GameState.LOGGED_IN
                && client.getLocalPlayer() != null
                && client.getLocalPlayer().getName() != null;

        if (!isValidPlayerLoggedIn || !isSupportedProfile(profileType)) {
            return null;
        }

        final String player = client.getLocalPlayer().getName();
        if (state == null
                || !state.ownedPlayer.equals(player)
                || state.ownedProfileType != profileType
                || state.accountHash != client.getAccountHash()) {
            reset();
            state = new PlayerState(player, profileType, client.getAccountHash());
        }

        activePlayerName = player;
        return state;
    }

    public void reset() {
        activePlayerName = null;
        state = null;
        flatMostRecent = null;
        flatRef.set(null);
        isMemberInGroup = false;
        skipNextNAttempts = 0;
    }

    private boolean isSupportedProfile(RuneScapeProfileType profileType) {
        return profileType == RuneScapeProfileType.STANDARD || LeagueMode.isEnabled(profileType);
    }

    public void onGameStateChanged(GameStateChanged event) {
        if (event.getGameState() == GameState.LOGIN_SCREEN) {
            activePlayerName = null;
        }
        if (state != null) {
            state.collectionLogManager.onGameStateChanged(event);
        }
    }

    /** Call from the Client thread. Releases state updates to the request thread. */
    public void stageForSubmitToAPI() {
        FlatState full = state.flatten();
        FlatState trimmed = full;

        if (flatMostRecent != null && trimmed.ownedPlayer.equals(flatMostRecent.ownedPlayer)) {
            trimmed = FlatState.diffKeepChangedFields(trimmed, flatMostRecent);
        }
        flatMostRecent = full;

        // Carry forward the updates that the submission thread has not yet consumed.

        FlatState notYetSubmitted = flatRef.get();
        FlatState combined = trimmed;
        if (notYetSubmitted != null) {
            combined = FlatState.combineWithPriority(trimmed, notYetSubmitted);
        }

        final boolean raceOccurred = !flatRef.compareAndSet(notYetSubmitted, combined);
        if (!raceOccurred) {
            return;
        }

        if (!flatRef.compareAndSet(null, trimmed)) {
            log.error("Another thread wrote to flatRef.");
        }
    }

    /**
     * Call from the request thread. Performs all our network requests and authentication for posting player data to the
     * configured server. If playerName does not match the state we are given, this method aborts.
     *
     * @param playerName The player name to expect updates for.
     */
    public void submitToApi(String playerName) {
        if (skipNextNAttempts-- > 0) return;

        String groupToken = config.authorizationToken().trim();

        if (groupToken.isEmpty()) return;

        if (!isMemberInGroup) {
            isMemberInGroup = fetchIsMember(groupToken, playerName);
        }

        if (!isMemberInGroup) {
            log.debug("Skip POST: not a member. Backing off.");
            skipNextNAttempts = 10;
            return;
        }

        String url = apiUrlBuilder.getUpdateGroupMemberUrl();
        if (url == null) {
            log.debug("Skip POST: Update Group Member URL is null (check base URL and group name).");
            return;
        }

        FlatState flat = flatRef.get();
        if (flat == null || !flat.ownedPlayer.equals(playerName)) {
            // The Client thread changed players.
            // We exit and wait for next time since we don't know how out-of-date flat is.
            log.debug("Skip POST: Player changed. Backing off.");
            return;
        }
        while (!flatRef.compareAndSet(flat, null)) {
            flat = flatRef.get();
            if (flat == null || !flat.ownedPlayer.equals(playerName)) return;
        }

        Map<String, Object> updates = flat.serialize();

        if (!flat.hasChangesBeyondBaseline()) {
            log.debug("Skip POST: no changes to send (fields={})", updates.size());
            return;
        }

        HttpRequestService.HttpResponse response = httpRequestService.post(url, groupToken, updates);

        if (response.getCode() == 422) {
            isMemberInGroup = false;
        }
    }

    private boolean fetchIsMember(String groupToken, String playerName) {
        String url = apiUrlBuilder.getMembershipCheckUrl(playerName);
        if (url == null) {
            log.debug("Skip POST: Membership Check URL is null (check base URL and group name).");
            return false;
        }

        return httpRequestService.get(url, groupToken).isSuccessful();
    }
}

