package gimhub.items;

import gimhub.APISerializable;
import gimhub.items.containers.*;
import java.util.*;
import java.util.stream.Collectors;
import java.util.stream.Stream;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.events.*;
import net.runelite.api.gameval.*;
import net.runelite.client.game.ItemManager;

@Slf4j
public class ItemRepository {
    private final List<TrackedItemContainer> allContainers;

    private final BankItems bank = new BankItems();
    private final TackleBoxItems tackleBox = new TackleBoxItems();

    private final ItemTransferQueue itemTransferQueue = new ItemTransferQueue();

    private final TrackedItemContainer[] depositButtonContainers;
    private Map<Integer, Integer> depositButtonItemsStaged = null;
    private static final String DEPOSIT_CONTAINERS_MESSAGE = "You empty all of your containers into the bank.";

    public ItemRepository() {
        FishBarrelItems fishBarrel = new FishBarrelItems();
        fishBarrel.setBank(bank);

        depositButtonContainers = new TrackedItemContainer[] {
            new EssencePouchesItems(),
            new CoalBagItems(),
            fishBarrel,
            new PlankSackItems(),
            new HerbSackItems(bank),
            new GemBagItems(),
            new LootingBagItems(),
            new SeedBoxItems(),
        };
        final TrackedItemContainer[] otherContainers = new TrackedItemContainer[] {
            bank,
            new InventoryItems(),
            new EquipmentItems(),
            new SharedBankItems(),
            new PotionStorageItems(),
            new SeedVaultItems(),
            new ChuggingBarrelItems(),
            new StashUnitsItems(),
            new PohCostumeRoomItems(),
            new PohSpiceRackItems(),
            new PohPetHouseItems(),
            new PohServantsMoneybagItems(),
            new RunePouchItems(),
            new QuiverItems(),
            new MasterScrollBookItems(),
            new ToolLeprechaunItems(),
            new ElnockInquisitorItems(),
            tackleBox,
        };

        allContainers = Stream.of(Stream.of(otherContainers), Stream.of(depositButtonContainers))
                .flatMap(s -> s)
                .collect(Collectors.toList());
    }

    public void onItemContainerChanged(ItemContainer container, ItemManager itemManager) {
        for (TrackedItemContainer tracked : allContainers) {
            tracked.onItemContainerChanged(container, itemManager);
        }
    }

    public void onStatChanged(StatChanged event, ItemManager itemManager) {
        for (TrackedItemContainer tracked : allContainers) {
            tracked.onStatChanged(event, itemManager);
        }
    }

    public void onVarbitChanged(Client client, int varpId, int varbitId, ItemManager itemManager) {
        for (TrackedItemContainer tracked : allContainers) {
            tracked.onVarbitChanged(client, varpId, varbitId, itemManager);
        }
    }

    public void onChatMessage(Client client, ChatMessage event, ItemManager itemManager) {
        final ChatMessageType type = event.getType();
        final String msg = event.getMessage();

        if (type == ChatMessageType.GAMEMESSAGE
                && msg != null
                && msg.contains(DEPOSIT_CONTAINERS_MESSAGE)
                && depositButtonItemsStaged != null) {
            // The message event comes AFTER all the varbits change, so that's why we staged the items already.

            bank.addItems(depositButtonItemsStaged, itemManager);

            depositButtonItemsStaged = null;
        }

        for (TrackedItemContainer tracked : allContainers) {
            tracked.onChatMessage(client, event, itemManager);
        }
    }

    public void onGameTick(Client client, ItemManager itemManager) {
        final boolean bankIsOpen = client.getWidget(InterfaceID.Bankmain.UNIVERSE) != null;
        final boolean tackleBoxIsOpen = client.getWidget(InterfaceID.TackleBoxMain.UNIVERSE) != null;

        final ItemTransferQueue.TrackedContainers knownState = new ItemTransferQueue.TrackedContainers(
                ItemsUtilities.convertToSafeMap(client.getItemContainer(InventoryID.INV), itemManager),
                ItemsUtilities.convertToSafeMap(client.getItemContainer(InventoryID.WORN), itemManager),
                bank.getBankItems(),
                tackleBox.getTackleBoxItems());

        ItemTransferQueue.ContainersToUpdate updates = itemTransferQueue.onGameTick(
                knownState,
                new ItemTransferQueue.BankSettings(client),
                client.getTickCount(),
                bankIsOpen,
                tackleBoxIsOpen);

        if (!bankIsOpen && updates.bank != null) {
            bank.setItems(updates.bank, itemManager);
        }
        if (!tackleBoxIsOpen && updates.tackleBox != null) {
            tackleBox.setItems(updates.tackleBox, itemManager);
        }

        for (TrackedItemContainer tracked : allContainers) {
            tracked.onGameTick(client, itemManager);
        }
    }

    public void onMenuOptionClicked(Client client, MenuOptionClicked event, ItemManager itemManager) {
        final boolean clickedDepositContainersButton =
                event.getParam1() == InterfaceID.BankDepositbox.DEPOSIT_LOOTINGBAG
                        || event.getParam1() == InterfaceID.Bankmain.DEPOSITCONTAINERS;
        if (clickedDepositContainersButton && depositButtonItemsStaged == null) {
            final ItemContainer inventory = client.getItemContainer(InventoryID.INV);
            if (inventory != null) {
                final Set<Integer> inventoryIDs = Arrays.stream(inventory.getItems())
                        .map(Item::getId)
                        .filter(itemID -> itemID >= 0)
                        .collect(Collectors.toSet());

                final Map<Integer, Integer> depositedItems = new HashMap<>();
                for (TrackedItemContainer container : depositButtonContainers) {
                    final Map<Integer, Integer> containerItems =
                            container.onDepositContainers(client, itemManager, inventoryIDs);
                    for (final Map.Entry<Integer, Integer> entry : containerItems.entrySet()) {
                        depositedItems.merge(entry.getKey(), entry.getValue(), Integer::sum);
                    }
                }
                depositButtonItemsStaged = depositedItems;
            }
            return;
        }

        itemTransferQueue.onMenuOptionClicked(client, event);

        for (TrackedItemContainer tracked : allContainers) {
            tracked.onMenuOptionClicked(client, event, itemManager);
        }
    }

    public void onWidgetLoaded(WidgetLoaded event) {
        for (TrackedItemContainer tracked : allContainers) {
            tracked.onWidgetLoaded(event);
        }
    }

    public void onScriptPreFired(Client client, ScriptPreFired event) {
        for (TrackedItemContainer tracked : allContainers) {
            tracked.onScriptPreFired(client, event);
        }
    }

    private static final int MESLAYERMODE_XQUERY = 7;

    public void onScriptPostFired(Client client, ScriptPostFired event) {
        for (TrackedItemContainer tracked : allContainers) {
            tracked.onScriptPostFired(client, event);
        }
        // This script converts strings with "K" "M" and "B" to a format without them
        final int PROCESS_STRING_SCRIPT = 212;
        final boolean isXQueryOpen = client.getVarcIntValue(VarClientID.MESLAYERMODE) == MESLAYERMODE_XQUERY;
        final Object scriptReturnValue = client.getObjectStack()[0];

        if (event.getScriptId() == PROCESS_STRING_SCRIPT && isXQueryOpen && scriptReturnValue instanceof String) {
            final int xQueryQuantity = Integer.parseInt((String) scriptReturnValue);
            itemTransferQueue.onXQuerySubmitted(xQueryQuantity, client.getTickCount());
        }
    }

    private int mesLayerMode = 0;

    public void onVarClientIntChanged(Client client, VarClientIntChanged event) {
        if (event.getIndex() != VarClientID.MESLAYERMODE) return;

        final int oldMode = mesLayerMode;
        final int newMode = client.getVarcIntValue(VarClientID.MESLAYERMODE);

        mesLayerMode = newMode;

        if (oldMode == MESLAYERMODE_XQUERY && newMode != MESLAYERMODE_XQUERY) {
            itemTransferQueue.cullQueryXActions();
        }
    }

    public void flatten(Map<String, APISerializable> flat) {
        for (TrackedItemContainer tracked : allContainers) {
            flat.put(tracked.key(), tracked.get());
        }
    }
}

package gimhub.items;

import gimhub.items.containers.TackleBoxItems;
import java.util.*;
import java.util.stream.Collectors;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;

@Slf4j
public class ItemTransferQueue {
    public static final class TrackedContainers {
        public final Map<Integer, Integer> inventory;
        public final Map<Integer, Integer> equipment;
        public final Map<Integer, Integer> bank;
        public final Map<Integer, Integer> tackleBox;

        TrackedContainers(
                Map<Integer, Integer> inventory,
                Map<Integer, Integer> equipment,
                Map<Integer, Integer> bank,
                Map<Integer, Integer> tackleBox) {
            this.inventory = inventory;
            this.equipment = equipment;
            this.bank = bank;
            this.tackleBox = tackleBox;
        }

        private TrackedContainers deepClone() {
            return new TrackedContainers(
                    new HashMap<>(inventory), new HashMap<>(equipment), new HashMap<>(bank), new HashMap<>(tackleBox));
        }

        @Override
        public boolean equals(Object o) {
            if (o == null) return false;
            if (!(o instanceof TrackedContainers)) return false;
            final TrackedContainers other = (TrackedContainers) o;

            final boolean inventoryEquals = inventory.equals(other.inventory);
            final boolean equipmentEquals = equipment.equals(other.equipment);
            final boolean bankEquals = bank.equals(other.bank);
            final boolean tackleBoxEquals = tackleBox.equals(other.tackleBox);

            return inventoryEquals && equipmentEquals && bankEquals && tackleBoxEquals;
        }
    }

    private static final class TrackedMenuOptionClicked {
        public final int itemOp;
        public final int itemId;
        public final int param0;
        public final int param1;
        public final int identifier;

        @Getter
        private int tickCount;

        @Getter
        private Integer queryXQuantity = null;

        public void setQueryXQuantity(int quantity, int tickCount) {
            // Refresh the tick count, since the timer for when we expect to observe it starts NOW
            this.tickCount = tickCount;
            this.queryXQuantity = quantity;
        }

        // Indicates that this event represents a "withdraw/deposit X" option in an item menu that pulls up the modal.
        public boolean isQueryXAction() {
            final boolean isBankside = param1 == InterfaceID.Bankside.ITEMS && identifier == 7;
            final boolean isBankmain = param1 == InterfaceID.Bankmain.ITEMS && identifier == 6;
            final boolean isBankDepositbox = param1 == InterfaceID.BankDepositbox.INVENTORY && identifier == 5;

            return isBankside || isBankmain || isBankDepositbox;
        }

        public TrackedMenuOptionClicked(MenuOptionClicked event, int tickCount) {
            this.itemOp = event.getItemOp();
            this.itemId = event.getItemId();
            this.param0 = event.getParam0();
            this.param1 = event.getParam1();
            this.identifier = event.getId();
            this.tickCount = tickCount;
        }
    }

    private static final int TICK_COUNT_FOR_ITEM_TRANSFER_DETECTION = 2;
    private static final Map<Integer, Integer> IDENTIFIER_FILL_BY_ITEM_ID =
            Map.ofEntries(Map.entry(ItemID.TACKLE_BOX, 3));
    private static final Map<Integer, Integer> IDENTIFIER_EMPTY_BY_ITEM_ID =
            Map.ofEntries(Map.entry(ItemID.TACKLE_BOX, 4));

    private static TransferDirection getInventoryTransferDirection(int itemId, int identifier) {
        final Integer fillIdentifier = IDENTIFIER_FILL_BY_ITEM_ID.get(itemId);
        if (fillIdentifier != null && identifier == fillIdentifier) {
            return TransferDirection.LOSS;
        }

        final Integer emptyIdentifier = IDENTIFIER_EMPTY_BY_ITEM_ID.get(itemId);
        if (emptyIdentifier != null && identifier == emptyIdentifier) {
            return TransferDirection.GAIN;
        }

        return TransferDirection.NONE;
    }

    private TrackedContainers previousTickState;
    private final List<TrackedMenuOptionClicked> itemOpQueue = new ArrayList<>();

    public static final class ContainersToUpdate {
        Map<Integer, Integer> bank = null;
        Map<Integer, Integer> tackleBox = null;
    }

    public static final class BankSettings {
        final int depositXQuantity;
        final int bankDefaultDepositQuantity;
        final int depositBoxDefaultDepositQuantity;

        public BankSettings(Client client) {
            this.depositXQuantity = client.getVarpValue(VarPlayerID.DEPOSITBOX_REQUESTEDQUANTITY);

            switch (client.getVarbitValue(VarbitID.BANK_QUANTITY_TYPE)) {
                case 0:
                    this.bankDefaultDepositQuantity = 1;
                    break;
                case 1:
                    this.bankDefaultDepositQuantity = 5;
                    break;
                case 2:
                    this.bankDefaultDepositQuantity = 10;
                    break;
                case 3:
                    this.bankDefaultDepositQuantity = this.depositXQuantity;
                    break;
                case 4:
                    this.bankDefaultDepositQuantity = Integer.MAX_VALUE;
                    break;
                default:
                    this.bankDefaultDepositQuantity = 0;
                    break;
            }

            switch (client.getVarbitValue(VarbitID.DEPOSITBOX_MODE)) {
                case 0:
                    this.depositBoxDefaultDepositQuantity = 1;
                    break;
                case 1:
                    this.depositBoxDefaultDepositQuantity = 5;
                    break;
                case 2:
                    this.depositBoxDefaultDepositQuantity = Integer.MAX_VALUE;
                    break;
                case 3:
                    this.depositBoxDefaultDepositQuantity = this.depositXQuantity;
                    break;
                case 4:
                    this.depositBoxDefaultDepositQuantity = 10;
                    break;
                default:
                    this.depositBoxDefaultDepositQuantity = 0;
                    break;
            }
        }
    }

    public ContainersToUpdate onGameTick(
            TrackedContainers knownState,
            BankSettings bankSettings,
            int tickCount,
            boolean isBankOpen,
            boolean isTackleBoxOpen) {
        itemOpQueue.removeIf(op -> {
            final boolean isUnfinishedQueryXAction = op.isQueryXAction() && op.getQueryXQuantity() == null;
            if (isUnfinishedQueryXAction) {
                return false;
            }

            return op.tickCount < tickCount - TICK_COUNT_FOR_ITEM_TRANSFER_DETECTION;
        });

        if (previousTickState == null || itemOpQueue.isEmpty()) {
            previousTickState = knownState.deepClone();
            return new ContainersToUpdate();
        }

        final TrackedContainers assumedStart = previousTickState.deepClone();
        TrackedContainers assumedNow = assumedStart.deepClone();
        final ArrayList<TrackedContainers> assumedCheckpoints = new ArrayList<>();

        for (final TrackedMenuOptionClicked op : itemOpQueue) {
            if (op.param1 == InterfaceID.Bankside.ITEMS) {
                boolean isDeposit = op.identifier >= 2 && op.identifier <= 8;
                boolean isUseFillEmpty = op.identifier == 9;
                if (isDeposit) {
                    final int depositedItemID = op.itemId;
                    Integer attemptedDepositQuantity = null;
                    switch (op.identifier) {
                        case 2:
                            attemptedDepositQuantity = bankSettings.bankDefaultDepositQuantity;
                            break;
                        case 3: // Deposit 1
                            attemptedDepositQuantity = 1;
                            break;
                        case 4: // Deposit 5
                            attemptedDepositQuantity = 5;
                            break;
                        case 5: // Deposit 10
                            attemptedDepositQuantity = 10;
                            break;
                        case 6: // Deposit X (actual)
                            attemptedDepositQuantity = bankSettings.depositXQuantity;
                            break;
                        case 7: // Deposit X (with prompt for amount)
                            attemptedDepositQuantity = op.getQueryXQuantity();
                            break;
                        case 8: // Deposit all
                            attemptedDepositQuantity = Integer.MAX_VALUE;
                            break;
                    }

                    if (attemptedDepositQuantity != null) {
                        final int inventoryQuantityNow = assumedNow.inventory.getOrDefault(depositedItemID, 0);
                        final int actualQuantityDeposited = Math.min(inventoryQuantityNow, attemptedDepositQuantity);

                        // We do not track containers that deposit directly from the bank, so this inference is mostly
                        // safe.
                        final int bankDiscrepancy = knownState.bank.getOrDefault(depositedItemID, 0)
                                - assumedNow.bank.getOrDefault(depositedItemID, 0);
                        final boolean depositOccurred = bankDiscrepancy >= actualQuantityDeposited;

                        if (actualQuantityDeposited > 0 && depositOccurred) {
                            assumedNow.inventory.merge(depositedItemID, -actualQuantityDeposited, Integer::sum);
                            assumedNow.bank.merge(depositedItemID, actualQuantityDeposited, Integer::sum);
                        }
                    }
                } else if (isUseFillEmpty && op.itemId == ItemID.TACKLE_BOX) {
                    final TransferDirection inventoryExpectedChanges = determineNetLaterMinusNow(
                            assumedNow.inventory, knownState.inventory, TackleBoxItems.getItemFilter());
                    final Map<Integer, Integer> transferQuantities = filterLaterMinusNow(
                            assumedNow.inventory,
                            knownState.inventory,
                            TackleBoxItems.getItemFilter(),
                            inventoryExpectedChanges);
                    performTransfer(assumedNow.tackleBox, assumedNow.inventory, transferQuantities);
                }
            } else if (op.param1 == InterfaceID.BankDepositbox.INVENTORY) {
                boolean isDeposit = op.identifier >= 1 && op.identifier <= 6;
                boolean isUseFillEmpty = op.identifier == 9;
                if (isDeposit) {
                    final int depositedItemID = op.itemId;
                    Integer attemptedDepositQuantity = null;
                    switch (op.identifier) {
                        case 1: // Default
                            attemptedDepositQuantity = bankSettings.depositBoxDefaultDepositQuantity;
                            break;
                        case 2: // Deposit 1
                            attemptedDepositQuantity = 1;
                            break;
                        case 3: // Deposit 5
                            attemptedDepositQuantity = 5;
                            break;
                        case 4: // Deposit 10
                            attemptedDepositQuantity = 10;
                            break;
                        case 5: // Deposit X (with prompt for amount)
                            attemptedDepositQuantity = op.getQueryXQuantity();
                            break;
                        case 6: // Deposit all
                            attemptedDepositQuantity = Integer.MAX_VALUE;
                            break;
                    }

                    if (attemptedDepositQuantity != null) {
                        final int inventoryQuantityNow = assumedNow.inventory.getOrDefault(depositedItemID, 0);
                        final int actualQuantityDeposited = Math.min(inventoryQuantityNow, attemptedDepositQuantity);

                        // Sometimes clicking an item does not deposit it. This may be confused with filling a container
                        // while depositing, but that case seems rare enough to not matter.
                        final int inventoryDiscrepancy =
                                knownState.inventory.getOrDefault(depositedItemID, 0) - inventoryQuantityNow;
                        final boolean depositOccurred = inventoryDiscrepancy <= -actualQuantityDeposited;

                        if (actualQuantityDeposited > 0 && depositOccurred) {
                            assumedNow.inventory.merge(depositedItemID, -actualQuantityDeposited, Integer::sum);
                            assumedNow.bank.merge(depositedItemID, actualQuantityDeposited, Integer::sum);
                        }
                    }
                } else if (isUseFillEmpty && op.itemId == ItemID.TACKLE_BOX) {
                    final TransferDirection inventoryExpectedChanges = determineNetLaterMinusNow(
                            assumedNow.inventory, knownState.inventory, TackleBoxItems.getItemFilter());
                    final Map<Integer, Integer> transferQuantities = filterLaterMinusNow(
                            assumedNow.inventory,
                            knownState.inventory,
                            TackleBoxItems.getItemFilter(),
                            inventoryExpectedChanges);
                    performTransfer(assumedNow.tackleBox, assumedNow.inventory, transferQuantities);
                }
            } else if (op.param1 == InterfaceID.Bankmain.ITEMS) {
                boolean isWithdraw = op.identifier >= 1 && op.identifier <= 8;
                if (isWithdraw) {
                    final int withdrawnItemID = op.itemId;
                    Integer attemptedWithdrawQuantity = null;
                    switch (op.identifier) {
                        case 1: // Withdraw default
                            attemptedWithdrawQuantity = bankSettings.bankDefaultDepositQuantity;
                            break;
                        case 2: // Withdraw 1
                            attemptedWithdrawQuantity = 1;
                            break;
                        case 3: // Withdraw 5
                            attemptedWithdrawQuantity = 5;
                            break;
                        case 4: // Withdraw 10
                            attemptedWithdrawQuantity = 10;
                            break;
                        case 5: // Withdraw X (actual)
                            attemptedWithdrawQuantity = bankSettings.depositXQuantity;
                            break;
                        case 6: // Withdraw X (with prompt for amount)
                            attemptedWithdrawQuantity = op.getQueryXQuantity();
                            break;
                        case 7: // Withdraw all
                            attemptedWithdrawQuantity = Integer.MAX_VALUE;
                            break;
                        case 8: // Withdraw all but 1
                            attemptedWithdrawQuantity = assumedNow.bank.getOrDefault(withdrawnItemID, 0) - 1;
                            break;
                    }

                    if (attemptedWithdrawQuantity != null && attemptedWithdrawQuantity > 0) {
                        final int bankQuantityNow = assumedNow.bank.getOrDefault(withdrawnItemID, 0);
                        final int actualQuantityWithdrawn = Math.min(bankQuantityNow, attemptedWithdrawQuantity);

                        // We do not track containers that draw directly from the bank, so this inference is mostly
                        // safe.
                        final int bankDiscrepancy = knownState.bank.getOrDefault(withdrawnItemID, 0) - bankQuantityNow;
                        final boolean withdrawalOccurred = bankDiscrepancy <= -actualQuantityWithdrawn;

                        if (actualQuantityWithdrawn > 0 && withdrawalOccurred) {
                            assumedNow.inventory.merge(withdrawnItemID, actualQuantityWithdrawn, Integer::sum);
                            assumedNow.bank.merge(withdrawnItemID, -actualQuantityWithdrawn, Integer::sum);
                        }
                    }
                }
            } else if (op.param1 == InterfaceID.Inventory.ITEMS) {
                final TransferDirection inventoryExpectedChanges =
                        getInventoryTransferDirection(op.itemId, op.identifier);
                if (inventoryExpectedChanges != TransferDirection.NONE) {
                    final Map<Integer, Integer> transferQuantities = filterLaterMinusNow(
                            assumedNow.inventory,
                            knownState.inventory,
                            TackleBoxItems.getItemFilter(),
                            inventoryExpectedChanges);
                    performTransfer(assumedNow.tackleBox, assumedNow.inventory, transferQuantities);
                }
            } else if (op.param1 == InterfaceID.BankDepositbox.DEPOSIT_INV) {
                for (final int itemID : assumedNow.inventory.keySet()) {
                    final int quantityTransferred = assumedNow.inventory.getOrDefault(itemID, 0);
                    assumedNow.inventory.merge(itemID, -quantityTransferred, Integer::sum);
                    assumedNow.bank.merge(itemID, quantityTransferred, Integer::sum);
                }
            } else if (op.param1 == InterfaceID.BankDepositbox.DEPOSIT_WORN) {
                for (final int itemID : assumedNow.equipment.keySet()) {
                    final int quantityTransferred = assumedNow.equipment.getOrDefault(itemID, 0);
                    assumedNow.equipment.merge(itemID, -quantityTransferred, Integer::sum);
                    assumedNow.bank.merge(itemID, quantityTransferred, Integer::sum);
                }
            } else if (op.param1 == InterfaceID.Bankmain.DEPOSITINV) {
                for (final int itemID : assumedNow.inventory.keySet()) {
                    final int quantityTransferred = assumedNow.inventory.getOrDefault(itemID, 0);
                    assumedNow.inventory.merge(itemID, -quantityTransferred, Integer::sum);
                    assumedNow.bank.merge(itemID, quantityTransferred, Integer::sum);
                }
            } else if (op.param1 == InterfaceID.Bankmain.DEPOSITWORN) {
                for (final int itemID : assumedNow.equipment.keySet()) {
                    final int quantityTransferred = assumedNow.equipment.getOrDefault(itemID, 0);
                    assumedNow.equipment.merge(itemID, -quantityTransferred, Integer::sum);
                    assumedNow.bank.merge(itemID, quantityTransferred, Integer::sum);
                }
            } else {
                continue;
            }

            assumedCheckpoints.add(assumedNow.deepClone());
        }

        if (assumedCheckpoints.isEmpty()) {
            previousTickState = knownState.deepClone();
            return new ContainersToUpdate();
        }

        int idxOfLastBalancedCheckpoint = -1;

        final Set<Integer> itemsRequiredToBeBalanced = Set.copyOf(TackleBoxItems.getItemFilter());
        for (int checkpointIdx = assumedCheckpoints.size() - 1; checkpointIdx >= 0; checkpointIdx--) {
            final TrackedContainers checkpoint = assumedCheckpoints.get(checkpointIdx);

            final boolean checkpointIsIdenticalToPrevious;
            if (checkpointIdx > 0) {
                checkpointIsIdenticalToPrevious = checkpoint.equals(assumedCheckpoints.get(checkpointIdx - 1));
            } else {
                checkpointIsIdenticalToPrevious = checkpoint.equals(assumedStart);
            }

            if (checkpointIsIdenticalToPrevious) {
                continue;
            }

            boolean checkpointIsBalancedWithKnownState = itemsRequiredToBeBalanced.stream()
                    .allMatch(itemID -> {
                        final boolean isInventorySettled = Objects.equals(
                                checkpoint.inventory.getOrDefault(itemID, 0),
                                knownState.inventory.getOrDefault(itemID, 0));
                        final boolean isEquipmentSettled = Objects.equals(
                                checkpoint.equipment.getOrDefault(itemID, 0),
                                knownState.equipment.getOrDefault(itemID, 0));
                        final boolean isBankSettled = !isBankOpen
                                || Objects.equals(
                                        checkpoint.bank.getOrDefault(itemID, 0),
                                        knownState.bank.getOrDefault(itemID, 0));

                        return isInventorySettled && isEquipmentSettled && isBankSettled;
                    });

            if (checkpointIsBalancedWithKnownState) {
                idxOfLastBalancedCheckpoint = checkpointIdx;
                break;
            }
        }

        if (idxOfLastBalancedCheckpoint < 0 || idxOfLastBalancedCheckpoint >= assumedCheckpoints.size()) {
            previousTickState = knownState.deepClone();
            return new ContainersToUpdate();
        }

        TrackedContainers mostUpToDateCheckpoint = assumedCheckpoints.get(idxOfLastBalancedCheckpoint);

        ContainersToUpdate result = new ContainersToUpdate();

        result.bank = mostUpToDateCheckpoint.bank.entrySet().stream()
                .filter(entry -> entry.getValue() != 0)
                .collect(Collectors.toMap(Map.Entry::getKey, Map.Entry::getValue));
        result.tackleBox = mostUpToDateCheckpoint.tackleBox.entrySet().stream()
                .filter(entry -> entry.getValue() != 0)
                .collect(Collectors.toMap(Map.Entry::getKey, Map.Entry::getValue));

        itemOpQueue.subList(0, idxOfLastBalancedCheckpoint + 1).clear();

        /*
         * This may cause issues when the player opens the bank/tacklebox, since that could cause the next
         * invocation of this method to attempt to attribute that massive influx/outflux of items to some
         * user input.
         *
         * Hopefully not an issue: the returned ContainersToUpdate should only be copied out when the bank/tacklebox
         * are closed.
         *
         * Copying from knownState where possible helps smooth out desync.
         */
        previousTickState = new TrackedContainers(
                knownState.inventory,
                knownState.equipment,
                isBankOpen ? knownState.bank : result.bank,
                isTackleBoxOpen ? knownState.tackleBox : result.tackleBox);
        return result;
    }

    // Given a filter of item IDs, determines if there was a net loss or gain of those items from now until end.
    private enum TransferDirection {
        LOSS,
        GAIN,
        NONE
    }

    private static TransferDirection determineNetLaterMinusNow(
            Map<Integer, Integer> now, Map<Integer, Integer> later, Set<Integer> filterItemIDs) {
        int lossCount = 0;
        int gainCount = 0;

        for (final Integer itemID : filterItemIDs) {
            final int difference = later.getOrDefault(itemID, 0) - now.getOrDefault(itemID, 0);

            if (difference > 0) {
                gainCount++;
            } else if (difference < 0) {
                lossCount++;
            }
        }

        if (gainCount > lossCount) {
            return TransferDirection.GAIN;
        }

        if (gainCount < lossCount) {
            return TransferDirection.LOSS;
        }

        return TransferDirection.NONE;
    }

    private static Map<Integer, Integer> filterLaterMinusNow(
            Map<Integer, Integer> now,
            Map<Integer, Integer> later,
            Set<Integer> filterItemIDs,
            TransferDirection filterDirection) {
        final Map<Integer, Integer> result = new HashMap<>();

        if (filterDirection == TransferDirection.NONE) {
            return result;
        }

        for (final Integer itemID : filterItemIDs) {
            final int difference = later.getOrDefault(itemID, 0) - now.getOrDefault(itemID, 0);

            switch (filterDirection) {
                case LOSS:
                    if (difference < 0) {
                        result.put(itemID, difference);
                    }
                    break;
                case GAIN:
                    if (difference > 0) {
                        result.put(itemID, difference);
                    }
                    break;
            }
        }

        return result;
    }

    // Subtracts quantities from source, adds them to destination.
    // Positive quantities represent movement from source to destination, and negative vice-versa.
    private static void performTransfer(
            Map<Integer, Integer> source, Map<Integer, Integer> destination, Map<Integer, Integer> transferQuantities) {
        for (final Map.Entry<Integer, Integer> entry : transferQuantities.entrySet()) {
            final int itemID = entry.getKey();
            final int quantity = entry.getValue();

            if (quantity == 0) {
                continue;
            }
            source.merge(itemID, -quantity, Integer::sum);
            destination.merge(itemID, quantity, Integer::sum);
        }
    }

    public void onXQuerySubmitted(int quantity, int tickCount) {
        for (int opIdx = itemOpQueue.size() - 1; opIdx >= 0; opIdx--) {
            TrackedMenuOptionClicked op = itemOpQueue.get(opIdx);

            if (!op.isQueryXAction()) continue;

            if (op.getQueryXQuantity() == null) {
                op.setQueryXQuantity(quantity, tickCount);
            }

            break;
        }
    }

    public void cullQueryXActions() {
        itemOpQueue.removeIf(op -> {
            if (!op.isQueryXAction()) {
                return false;
            }

            final Integer quantity = op.getQueryXQuantity();
            return quantity == null || quantity <= 0;
        });
    }

    public void onMenuOptionClicked(Client client, MenuOptionClicked event) {
        final TrackedMenuOptionClicked op = new TrackedMenuOptionClicked(event, client.getTickCount());

        final boolean isOpTracked;
        if (op.param1 == InterfaceID.Bankside.ITEMS) {
            final boolean isDeposit = op.identifier >= 2 && op.identifier <= 8;
            final boolean isUseFillEmpty = op.identifier == 9;
            isOpTracked = isDeposit || isUseFillEmpty;
        } else if (op.param1 == InterfaceID.BankDepositbox.INVENTORY) {
            final boolean isDeposit = op.identifier >= 1 && op.identifier <= 6;
            final boolean isUseFillEmpty = op.identifier == 9;
            isOpTracked = isDeposit || isUseFillEmpty;
        } else if (op.param1 == InterfaceID.Bankmain.ITEMS) {
            isOpTracked = op.identifier >= 1 && op.identifier <= 8;
        } else if (op.param1 == InterfaceID.Inventory.ITEMS) {
            isOpTracked = getInventoryTransferDirection(op.itemId, op.identifier) != TransferDirection.NONE;
        } else
            isOpTracked = op.param1 == InterfaceID.BankDepositbox.DEPOSIT_INV
                    || op.param1 == InterfaceID.BankDepositbox.DEPOSIT_WORN
                    || op.param1 == InterfaceID.Bankmain.DEPOSITINV
                    || op.param1 == InterfaceID.Bankmain.DEPOSITWORN;

        if (!isOpTracked) {
            return;
        }

        itemOpQueue.add(op);
    }
}

package gimhub.items;

import gimhub.APISerializable;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.client.game.ItemManager;

@Slf4j
public class ItemsOrdered implements APISerializable {
    private final List<ItemContainerItem> items;

    public ItemsOrdered() {
        items = new ArrayList<>();
    }

    public ItemsOrdered(Iterable<Item> container, ItemManager itemManager) {
        this.items = new ArrayList<>();

        for (final Item item : container) {
            if (!ItemsUtilities.isItemValid(item, itemManager)) {
                items.add(new ItemContainerItem(0, 0));
            } else {
                items.add(new ItemContainerItem(itemManager.canonicalize(item.getId()), item.getQuantity()));
            }
        }
    }

    /**
     * Specifying the size is required, since Runescape does not pad inventory and equipment. For example, if you do not
     * have ammo equipped, the equipment ItemContainer will have 13 items instead of 14 as we require.
     */
    public ItemsOrdered(ItemContainer container, ItemManager itemManager, int size) {
        this.items = new ArrayList<>();

        for (int i = 0; i < size; i++) {
            Item item = container.getItem(i);

            if (!ItemsUtilities.isItemValid(item, itemManager)) {
                items.add(new ItemContainerItem(0, 0));
            } else {
                items.add(new ItemContainerItem(itemManager.canonicalize(item.getId()), item.getQuantity()));
            }
        }
    }

    public Iterable<ItemContainerItem> getItems() {
        return items;
    }

    public Map<Integer, Integer> getUnorderedMap() {
        return items.stream().collect(Collectors.toMap(ItemContainerItem::getId, ItemContainerItem::getQuantity));
    }

    public Object serialize() {
        List<Integer> result = new ArrayList<>(items.size() * 2);

        for (ItemContainerItem item : items) {
            result.add(item.getId());
            result.add(Math.max(0, item.getQuantity()));
        }

        return result;
    }

    @Override
    public boolean equals(Object o) {
        if (o == this) return true;
        if (!(o instanceof ItemsOrdered)) return false;
        ItemsOrdered other = (ItemsOrdered) o;
        return other.items.equals(items);
    }
}

package gimhub.items;

import gimhub.APISerializable;
import java.util.*;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ItemContainer;
import net.runelite.client.game.ItemManager;

@Slf4j
public class ItemsUnordered implements APISerializable {
    @Getter
    private final Map<Integer, Integer> itemsQuantityByID;

    public ItemsUnordered() {
        this.itemsQuantityByID = new HashMap<>();
    }

    public ItemsUnordered(ItemsUnordered items) {
        this.itemsQuantityByID = new HashMap<>();

        if (items == null) {
            return;
        }

        this.itemsQuantityByID.putAll(items.itemsQuantityByID);
    }

    public ItemsUnordered(ItemsOrdered items) {
        this.itemsQuantityByID = new HashMap<>();

        if (items == null) {
            return;
        }

        for (final ItemContainerItem item : items.getItems()) {
            final int itemID = item.getId();
            final int quantity = itemsQuantityByID.getOrDefault(itemID, 0) + item.getQuantity();
            itemsQuantityByID.put(itemID, quantity);
        }
    }

    public ItemsUnordered(ItemContainer container, ItemManager itemManager) {
        itemsQuantityByID = ItemsUtilities.convertToSafeMap(container, itemManager);
    }

    public ItemsUnordered(Map<Integer, Integer> itemsQuantityByID, ItemManager itemManager) {
        this.itemsQuantityByID = ItemsUtilities.convertToSafeMap(itemsQuantityByID, itemManager);
    }

    @Override
    public Object serialize() {
        List<Integer> result = new ArrayList<>(itemsQuantityByID.size() * 2);

        for (final Map.Entry<Integer, Integer> entry : itemsQuantityByID.entrySet()) {
            final int itemID = entry.getKey();
            final int quantity = entry.getValue();

            if (quantity == 0) {
                continue;
            }

            result.add(itemID);
            result.add(quantity);
        }

        return result;
    }

    @Override
    public APISerializable diff(APISerializable newer) {
        final ItemsUnordered result = new ItemsUnordered();

        if (newer == this) return result;
        if (!(newer instanceof ItemsUnordered)) return result;
        final ItemsUnordered newerCast = (ItemsUnordered) newer;

        for (final Map.Entry<Integer, Integer> entry : this.itemsQuantityByID.entrySet()) {
            final int itemID = entry.getKey();
            final int olderQuantity = entry.getValue();

            result.itemsQuantityByID.put(itemID, newerCast.itemsQuantityByID.getOrDefault(itemID, 0) - olderQuantity);
        }
        for (final Map.Entry<Integer, Integer> entry : newerCast.itemsQuantityByID.entrySet()) {
            final int itemID = entry.getKey();

            if (result.itemsQuantityByID.containsKey(itemID)) {
                continue;
            }

            final int newerQuantity = entry.getValue();

            result.itemsQuantityByID.put(itemID, newerQuantity - this.itemsQuantityByID.getOrDefault(itemID, 0));
        }

        return result;
    }

    @Override
    public boolean equals(Object o) {
        if (o == this) return true;
        if (!(o instanceof ItemsUnordered)) return false;
        ItemsUnordered other = (ItemsUnordered) o;
        return other.itemsQuantityByID.equals(this.itemsQuantityByID);
    }
}

package gimhub.items;

import java.util.HashMap;
import java.util.Map;
import javax.annotation.Nullable;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.client.game.ItemManager;

public final class ItemsUtilities {
    private ItemsUtilities() {}

    public static boolean isItemValid(Item item, ItemManager itemManager) {
        if (item == null) return false;
        final int id = item.getId();
        if (itemManager != null) {
            final boolean isPlaceholder = itemManager.getItemComposition(id).getPlaceholderTemplateId() != -1;

            return id >= 0 && !isPlaceholder;
        }
        return false;
    }

    public static Map<Integer, Integer> convertToSafeMap(
            @Nullable Map<Integer, Integer> itemsQuantityByID, ItemManager itemManager) {
        final Map<Integer, Integer> resultQuantityByID = new HashMap<>();
        if (itemsQuantityByID == null) {
            return resultQuantityByID;
        }

        for (final Map.Entry<Integer, Integer> entry : itemsQuantityByID.entrySet()) {
            final Item item = new Item(entry.getKey(), entry.getValue());
            if (!ItemsUtilities.isItemValid(item, itemManager)) {
                continue;
            }

            final int itemID = itemManager.canonicalize(item.getId());
            resultQuantityByID.merge(itemID, item.getQuantity(), Integer::sum);
        }

        return resultQuantityByID;
    }

    public static Map<Integer, Integer> convertToSafeMap(@Nullable ItemContainer container, ItemManager itemManager) {
        final Map<Integer, Integer> resultQuantityByID = new HashMap<>();
        if (container == null) {
            return resultQuantityByID;
        }

        Item[] contents = container.getItems();
        for (final Item item : contents) {
            if (!ItemsUtilities.isItemValid(item, itemManager)) {
                continue;
            }

            final int itemID = itemManager.canonicalize(item.getId());
            resultQuantityByID.merge(itemID, item.getQuantity(), Integer::sum);
        }

        return resultQuantityByID;
    }
}

package gimhub.items.containers;

import gimhub.APISerializable;
import gimhub.items.ItemsUnordered;
import gimhub.items.ItemsUtilities;
import java.util.HashMap;
import java.util.Map;
import net.runelite.api.ItemContainer;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.game.ItemManager;

public class BankItems implements TrackedItemContainer {
    private ItemsUnordered items = null;
    private boolean known = false;

    public Map<Integer, Integer> getBankItems() {
        if (items == null) {
            return new HashMap<>();
        }
        return new HashMap<>(items.getItemsQuantityByID());
    }

    @Override
    public String key() {
        if (!known) {
            return "bank_partial";
        }
        return "bank";
    }

    @Override
    public APISerializable get() {
        return items;
    }

    @Override
    public void onItemContainerChanged(ItemContainer container, ItemManager itemManager) {
        if (container.getId() == InventoryID.BANK) {
            items = new ItemsUnordered(container, itemManager);
            known = true;
        }
    }

    public void setItems(Map<Integer, Integer> items, ItemManager itemManager) {
        if (this.items == null && items.isEmpty()) {
            return;
        }

        this.items = new ItemsUnordered(items, itemManager);
    }

    public void addItems(Map<Integer, Integer> items, ItemManager itemManager) {
        final Map<Integer, Integer> additionalItemsSafe = ItemsUtilities.convertToSafeMap(items, itemManager);
        final Map<Integer, Integer> resultItems = getBankItems();

        for (final Map.Entry<Integer, Integer> entry : additionalItemsSafe.entrySet()) {
            final int itemID = entry.getKey();
            final int quantity = entry.getValue();
            if (quantity <= 0) {
                continue;
            }
            resultItems.merge(itemID, quantity, Integer::sum);
        }
        this.items = new ItemsUnordered(resultItems, itemManager);
    }
}

package gimhub.items.containers;

import gimhub.APISerializable;
import gimhub.items.ItemsUnordered;
import gimhub.items.ItemsUtilities;
import java.util.HashMap;
import java.util.Map;
import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.ItemContainer;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.game.ItemManager;

abstract class ChatStorageItems implements TrackedItemContainer {
    protected ItemsUnordered items;
    protected final Set<Integer> containerIds;
    protected final Set<Integer> contentIds;
    protected Map<Integer, Integer> beforeTransfer;
    protected boolean filling;
    protected int transferDeadline;
    protected Map<Integer, Integer> bankBeforeTransfer;
    protected boolean depositing;

    protected ChatStorageItems(Set<Integer> containerIds, Set<Integer> contentIds) {
        this.containerIds = containerIds;
        this.contentIds = contentIds;
    }

    @Override
    public APISerializable get() {
        return items;
    }

    protected void setItems(Map<Integer, Integer> contents, ItemManager itemManager) {
        items = new ItemsUnordered(contents, itemManager);
        beforeTransfer = null;
    }

    protected void addItem(int itemId, int quantity, ItemManager itemManager) {
        if (items == null) {
            return;
        }
        Map<Integer, Integer> contents = new HashMap<>(items.getItemsQuantityByID());
        contents.merge(itemId, quantity, Integer::sum);
        items = new ItemsUnordered(contents, itemManager);
    }

    @Override
    public void onMenuOptionClicked(Client client, MenuOptionClicked event, ItemManager itemManager) {
        if (items == null) {
            return;
        }
        Widget selected = client.getSelectedWidget();
        boolean usingItem = selected != null
                && ((containerIds.contains(event.getItemId()) && contentIds.contains(selected.getItemId()))
                        || (contentIds.contains(event.getItemId()) && containerIds.contains(selected.getItemId())));
        if ((containerIds.contains(event.getItemId())
                        && (event.getMenuOption().equals("Fill")
                                || event.getMenuOption().equals("Empty")))
                || usingItem) {
            ItemContainer inventory = client.getItemContainer(InventoryID.INV);
            if (inventory != null) {
                beforeTransfer = ItemsUtilities.convertToSafeMap(inventory, itemManager);
                transferDeadline = client.getTickCount() + 3;
                ItemContainer bank = client.getItemContainer(InventoryID.BANK);
                bankBeforeTransfer = bank == null ? null : ItemsUtilities.convertToSafeMap(bank, itemManager);
                filling = usingItem || event.getMenuOption().equals("Fill");
            }
        }
    }

    @Override
    public void onGameTick(Client client, ItemManager itemManager) {
        if (beforeTransfer == null) {
            return;
        }
        ItemContainer inventory = client.getItemContainer(InventoryID.INV);
        if (inventory == null) {
            beforeTransfer = null;
            return;
        }
        Map<Integer, Integer> current = ItemsUtilities.convertToSafeMap(inventory, itemManager);
        boolean changed = false;
        ItemContainer bank = client.getItemContainer(InventoryID.BANK);
        Map<Integer, Integer> currentBank = bank == null ? null : ItemsUtilities.convertToSafeMap(bank, itemManager);
        for (int itemId : contentIds) {
            int difference = beforeTransfer.getOrDefault(itemId, 0) - current.getOrDefault(itemId, 0);
            if (!filling && difference == 0 && bankBeforeTransfer != null && currentBank != null) {
                difference = bankBeforeTransfer.getOrDefault(itemId, 0) - currentBank.getOrDefault(itemId, 0);
            }
            if ((filling && difference > 0) || (!filling && difference < 0)) {
                int previous = items.getItemsQuantityByID().getOrDefault(itemId, 0);
                addItem(itemId, Math.max(-previous, difference), itemManager);
                changed = true;
            }
        }
        if (changed || client.getTickCount() >= transferDeadline) {
            beforeTransfer = null;
        }
    }

    @Override
    public Map<Integer, Integer> onDepositContainers(
            Client client, ItemManager itemManager, Set<Integer> inventoryIds) {
        depositing = inventoryIds.stream().anyMatch(containerIds::contains);
        return depositing && items != null ? Map.copyOf(items.getItemsQuantityByID()) : Map.of();
    }

    protected boolean confirmDeposit(String message, ItemManager itemManager) {
        if (depositing && message.equals("You empty all of your containers into the bank.")) {
            depositing = false;
            setItems(Map.of(), itemManager);
            return true;
        }
        return false;
    }
}

package gimhub.items.containers;

import gimhub.items.ItemsUnordered;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import java.util.stream.Collectors;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.game.ItemManager;
import net.runelite.client.util.Text;

public class ChuggingBarrelItems extends ContainerItems {
    protected static final Pattern DEPOSIT =
            Pattern.compile("Your chugging barrel has been filled with (\\d+) doses? of (.+)\\.");
    protected static final Pattern REMAINING = Pattern.compile("You have (\\d+) doses? of (.+) left in your barrel\\.");
    protected static final Pattern EMPTY = Pattern.compile("You have finished all doses of (.+) in your barrel\\.");

    protected static final Pattern DRINK = Pattern.compile("You drink (?:some of )?(?:the|your)? (.*)\\.");
    protected boolean drinking;
    protected boolean inspectDisassembly;

    @Override
    public void onMenuOptionClicked(Client client, MenuOptionClicked event, ItemManager itemManager) {
        if (event.getItemId() == ItemID.MM_PREPOT_DEVICE
                && event.getMenuOption().equals("Drink")) {
            drinking = true;
        }
    }

    @Override
    public void onWidgetLoaded(WidgetLoaded event) {
        super.onWidgetLoaded(event);
        if (event.getGroupId() == InterfaceID.OBJECTBOX_DOUBLE) {
            inspectDisassembly = true;
        }
    }

    protected final List<String> messages = new ArrayList<>();

    @Override
    public void onGameTick(Client client, ItemManager itemManager) {
        super.onGameTick(client, itemManager);
        if (!authoritativeUpdate) {
            for (String message : messages) {
                processMessage(client, message, itemManager);
            }
        }
        authoritativeUpdate = false;
        messages.clear();
        drinking = false;
        if (inspectDisassembly) {
            Widget text = client.getWidget(InterfaceID.ObjectboxDouble.TEXT);
            if (text != null && text.getText().equals("You disassemble the Chugging barrel.")) {
                items = new ItemsUnordered();
            }
            inspectDisassembly = false;
        }
    }

    public ChuggingBarrelItems() {
        super(InventoryID.PREPOT_DEVICE_INV, InterfaceID.PrepotDevice.UNIVERSE);
    }

    @Override
    public String key() {
        return "chugging_barrel";
    }

    @Override
    public void onChatMessage(Client client, ChatMessage event, ItemManager itemManager) {
        if (items == null
                || (event.getType() != ChatMessageType.GAMEMESSAGE && event.getType() != ChatMessageType.SPAM)) {
            return;
        }
        messages.add(Text.removeTags(event.getMessage()));
    }

    protected void processMessage(Client client, String message, ItemManager itemManager) {
        Matcher drink = DRINK.matcher(message);
        Matcher deposit = DEPOSIT.matcher(message);
        Matcher remaining = REMAINING.matcher(message);
        Matcher empty = EMPTY.matcher(message);
        if (drinking && drink.matches()) {
            List<Integer> candidates = ChuggingBarrelPotions.BY_DRINK_MESSAGE.get(drink.group(1));
            if (candidates != null) {
                List<Integer> stored = candidates.stream()
                        .filter(id -> items.getItemsQuantityByID().getOrDefault(id, 0) > 0)
                        .collect(Collectors.toList());
                // A generic drink message can describe multiple brews. Wait for exact game data in that case.
                if (stored.size() == 1) {
                    Map<Integer, Integer> contents = new HashMap<>(items.getItemsQuantityByID());
                    contents.computeIfPresent(stored.get(0), (id, quantity) -> quantity - 1);
                    items = new ItemsUnordered(contents, itemManager);
                }
            }
        } else if (deposit.matches()) {
            updatePotion(client, itemManager, deposit.group(2), Integer.parseInt(deposit.group(1)), true);
        } else if (remaining.matches()) {
            updatePotion(client, itemManager, remaining.group(2), Integer.parseInt(remaining.group(1)), false);
        } else if (empty.matches()) {
            updatePotion(client, itemManager, empty.group(1), 0, false);
        }
    }

    protected void updatePotion(Client client, ItemManager itemManager, String name, int quantity, boolean add) {
        Integer itemId = ChuggingBarrelPotions.BY_NAME.get(name);
        if (itemId != null) {
            Map<Integer, Integer> contents = new HashMap<>(items.getItemsQuantityByID());
            contents.put(itemId, quantity + (add ? contents.getOrDefault(itemId, 0) : 0));
            items = new ItemsUnordered(contents, itemManager);
        }
    }
}

package gimhub.items.containers;

import gimhub.APISerializable;
import gimhub.items.ItemsOrdered;
import gimhub.items.ItemsUnordered;
import gimhub.items.ItemsUtilities;
import java.util.*;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.*;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.events.StatChanged;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.game.ItemManager;

@Slf4j
public class CoalBagItems implements TrackedItemContainer {
    private ItemsUnordered items = null;

    private boolean hasOpenCoalBag = false;

    private Integer bagCoalAmount = null;
    private Integer inventoryCoalAmount = null;
    private Integer inventoryCatalystAmount = null;

    private static final int ACTION_LISTEN_TICKS = 2;
    private int minedCoalWithOpenBagTick = Integer.MIN_VALUE;

    private static final class SuperheatTrigger {
        final int tick;
        final int coalUsage;

        public SuperheatTrigger(int tick, int coalUsage) {
            this.tick = tick;
            this.coalUsage = coalUsage;
        }
    }

    private SuperheatTrigger superheatTrigger = null;

    private static final Pattern EMPTY_PATTERN = Pattern.compile("The coal bag is.* empty\\.");
    private static final Pattern ONE_LEFT_PATTERN = Pattern.compile("The coal bag.* contains one piece of coal\\.");
    private static final Pattern AMOUNT_PATTERN =
            Pattern.compile("The coal bag.* contains (?<amount>\\d+) pieces of coal\\.");

    private static final Pattern MINE_PATTERN = Pattern.compile("You manage to mine some (?<ore>\\w+)\\.");
    private static final String MINE_PATTERN_COAL_NAME = "coal";

    private static final Pattern MINE_ADDITIONAL_PATTERN = Pattern.compile(".* you to mine an additional ore\\.");

    private static final Pattern SUPERHEAT_PATTERN = Pattern.compile(
            "(?:<[^<>]*>)?Superheat Item(?:</[^<>]*>)?(?:<[^<>]*>)? -> (?:<[^<>]*>)?(?<spellTarget>[\\w ]*)(?:<[^<>]*>)?");

    @Override
    public String key() {
        return "coal_bag";
    }

    @Override
    public APISerializable get() {
        return items;
    }

    private void rebuildItems(ItemManager itemManager) {
        if (bagCoalAmount == null || bagCoalAmount <= 0) {
            items = new ItemsUnordered();
        } else {
            items = new ItemsUnordered(new ItemsOrdered(List.of(new Item(ItemID.COAL, bagCoalAmount)), itemManager));
        }
    }

    private void updateInventoryCoal(ItemContainer container, ItemManager itemManager) {
        hasOpenCoalBag = false;
        inventoryCoalAmount = 0;
        inventoryCatalystAmount = 0;

        for (final Item item : container.getItems()) {
            if (!ItemsUtilities.isItemValid(item, itemManager)) {
                continue;
            }

            final int itemId = itemManager.canonicalize(item.getId());
            if (itemId == ItemID.COAL) {
                inventoryCoalAmount += item.getQuantity();
            } else if (itemId == ItemID.COAL_BAG_OPEN) {
                hasOpenCoalBag = true;
            } else if (itemId == ItemID.SMITHING_CATALYST) {
                inventoryCatalystAmount += item.getQuantity();
            }
        }
    }

    @Override
    public void onItemContainerChanged(ItemContainer container, ItemManager itemManager) {
        if (container.getId() == InventoryID.INV) {
            updateInventoryCoal(container, itemManager);
        }
    }

    @Override
    public void onMenuOptionClicked(Client client, MenuOptionClicked event, ItemManager itemManager) {
        if (inventoryCoalAmount == null || bagCoalAmount == null) {
            return;
        }

        final String target = event.getMenuTarget();
        log.debug("target {}", target);

        final Matcher matcher = SUPERHEAT_PATTERN.matcher(target);
        if (!matcher.matches()) {
            return;
        }

        final String spellTarget = matcher.group("spellTarget").toLowerCase();
        final int currentTick = client.getTickCount();
        int coalUsage = 0;

        final boolean hasCatalyst = inventoryCatalystAmount > 0;
        switch (spellTarget) {
            case "lovakite ore":
            case "iron ore":
                if (hasCatalyst) {
                    coalUsage = 1;
                } else {
                    coalUsage = 2;
                }
                break;
            case "mithril ore":
                if (hasCatalyst) {
                    coalUsage = 2;
                } else {
                    coalUsage = 4;
                }
                break;
            case "adamantite ore":
                if (hasCatalyst) {
                    coalUsage = 3;
                } else {
                    coalUsage = 6;
                }
                break;
            case "runite ore":
                if (hasCatalyst) {
                    coalUsage = 4;
                } else {
                    coalUsage = 8;
                }
                break;
        }

        coalUsage -= inventoryCoalAmount;
        if (coalUsage > 0) {
            superheatTrigger = new SuperheatTrigger(currentTick, coalUsage);
        }
    }

    @Override
    public void onStatChanged(StatChanged event, ItemManager itemManager) {
        if (event.getSkill() != Skill.SMITHING || superheatTrigger == null) {
            return;
        }

        if (superheatTrigger.coalUsage > 0) {
            bagCoalAmount -= superheatTrigger.coalUsage;
        }

        rebuildItems(itemManager);

        superheatTrigger = null;
    }

    @Override
    public void onGameTick(Client client, ItemManager itemManager) {
        if (superheatTrigger == null) {
            return;
        }

        final boolean isRecent = superheatTrigger.tick >= client.getTickCount() - ACTION_LISTEN_TICKS;
        if (!isRecent) {
            superheatTrigger = null;
        }
    }

    @Override
    public void onChatMessage(Client client, ChatMessage event, ItemManager itemManager) {
        ChatMessageType messageType = event.getType();
        String message = event.getMessage();
        if (messageType != ChatMessageType.GAMEMESSAGE || message == null) {
            return;
        }

        {
            final Matcher matcher = EMPTY_PATTERN.matcher(message);
            if (matcher.matches()) {
                bagCoalAmount = 0;
            }
        }
        {
            final Matcher matcher = ONE_LEFT_PATTERN.matcher(message);
            if (matcher.matches()) {
                bagCoalAmount = 1;
            }
        }
        {
            final Matcher matcher = AMOUNT_PATTERN.matcher(message);
            if (matcher.matches()) {
                try {
                    bagCoalAmount = Integer.parseInt(matcher.group("amount"));
                } catch (NumberFormatException ignored) {
                }
            }
        }

        if (hasOpenCoalBag) {
            final Matcher matcher = MINE_PATTERN.matcher(message);
            if (matcher.matches()) {
                final String ore = matcher.group("ore");
                if (Objects.equals(ore, MINE_PATTERN_COAL_NAME)) {
                    minedCoalWithOpenBagTick = client.getTickCount();
                    bagCoalAmount += 1;
                }
            }
        }

        final boolean hasMinedCoalRecently = minedCoalWithOpenBagTick >= client.getTickCount() - ACTION_LISTEN_TICKS;
        if (hasMinedCoalRecently) {
            final Matcher matcher = MINE_ADDITIONAL_PATTERN.matcher(message);
            if (matcher.matches()) {
                bagCoalAmount += 1;
            }
        }

        rebuildItems(itemManager);
    }

    @Override
    public Map<Integer, Integer> onDepositContainers(
            Client client, ItemManager itemManager, Set<Integer> inventoryIDs) {
        final boolean hasAnyCoalBag =
                inventoryIDs.contains(ItemID.COAL_BAG) || inventoryIDs.contains(ItemID.COAL_BAG_OPEN);
        if (!hasAnyCoalBag) {
            return new HashMap<>();
        }

        final Integer depositedCoalAmount = bagCoalAmount;
        bagCoalAmount = 0;
        rebuildItems(itemManager);

        if (depositedCoalAmount == null || depositedCoalAmount <= 0) {
            return new HashMap<>();
        }

        return Map.of(ItemID.COAL, depositedCoalAmount);
    }
}

package gimhub.items.containers;

import gimhub.APISerializable;
import gimhub.items.ItemsUnordered;
import java.util.Map;
import java.util.Set;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.ItemContainer;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.client.game.ItemManager;

abstract class ContainerItems implements TrackedItemContainer {
    protected ItemsUnordered items;
    protected final int inventoryId;
    protected final int interfaceRoot;
    protected final Set<Integer> containerIds;
    protected boolean depositing;
    protected boolean pending;
    protected boolean authoritativeUpdate;
    protected boolean firstTick = true;

    protected ContainerItems(int inventoryId, int interfaceRoot, Integer... containerIds) {
        this.inventoryId = inventoryId;
        this.interfaceRoot = interfaceRoot;
        this.containerIds = Set.of(containerIds);
    }

    @Override
    public APISerializable get() {
        return items;
    }

    @Override
    public void onItemContainerChanged(ItemContainer container, ItemManager itemManager) {
        if (container != null && container.getId() == inventoryId) {
            items = new ItemsUnordered(container, itemManager);
            authoritativeUpdate = true;
        }
    }

    @Override
    public Map<Integer, Integer> onDepositContainers(
            Client client, ItemManager itemManager, Set<Integer> inventoryIds) {
        depositing = inventoryIds.stream().anyMatch(containerIds::contains);
        return depositing && items != null ? Map.copyOf(items.getItemsQuantityByID()) : Map.of();
    }

    @Override
    public void onChatMessage(Client client, ChatMessage event, ItemManager itemManager) {
        if (depositing
                && event.getType() == ChatMessageType.GAMEMESSAGE
                && event.getMessage().equals("You empty all of your containers into the bank.")) {
            items = new ItemsUnordered();
            authoritativeUpdate = true;
            depositing = false;
        }
    }

    @Override
    public void onWidgetLoaded(WidgetLoaded event) {
        if (event.getGroupId() == (interfaceRoot >>> 16)) {
            pending = true;
        }
    }

    @Override
    public void onGameTick(Client client, ItemManager itemManager) {
        if (firstTick) {
            firstTick = false;
            pending = client.getWidget(interfaceRoot) != null;
        }
        if (!pending) {
            return;
        }
        if (client.getWidget(interfaceRoot) == null) {
            pending = false;
            return;
        }
        ItemContainer container = client.getItemContainer(inventoryId);
        if (container != null) {
            items = new ItemsUnordered(container, itemManager);
            authoritativeUpdate = true;
            pending = false;
        }
    }
}

