import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.junit.runners.Parameterized;

@RunWith(Parameterized.class)
public class PortableStorageItemsTest {
    @Parameterized.Parameters(name = "{0}")
    public static Collection<Object[]> containers() {
        return Arrays.asList(
                new Object[][] {{"herb_sack"}, {"looting_bag"}, {"seed_box"}, {"gem_bag"}, {"chugging_barrel"}});
    }

    @Parameterized.Parameter
    public String type;

    private Client client;
    private ItemManager itemManager;
    private TrackedItemContainer tracker;

    @Before
    public void setUp() {
        client = mock(Client.class);
        itemManager = mock(ItemManager.class);
        ItemComposition composition = mock(ItemComposition.class);
        when(composition.getPlaceholderTemplateId()).thenReturn(-1);
        when(itemManager.getItemComposition(anyInt())).thenReturn(composition);
        when(itemManager.canonicalize(anyInt())).thenAnswer(invocation -> invocation.getArgument(0));
        switch (type) {
            case "herb_sack":
                tracker = new HerbSackItems(new BankItems());
                break;
            case "looting_bag":
                tracker = new LootingBagItems();
                break;
            case "seed_box":
                tracker = new SeedBoxItems();
                break;
            case "gem_bag":
                tracker = new GemBagItems();
                break;
            default:
                tracker = new ChuggingBarrelItems();
        }
    }

    @Test
    public void readsRepresentativeContentsAndSerializesItemQuantities() {
        observe(12);
        assertEquals(type, tracker.key());
        assertEquals(Map.of(itemId(), 12), pairs(tracker.get()));
    }

    @Test
    public void confirmedEmptyClearsAnEarlierSnapshot() {
        observe(12);
        observe(0);
        assertEquals(List.of(), tracker.get().serialize());
    }

    @Test
    public void missingDataAndClosedInterfacesPreserveKnownContents() {
        assertNull(tracker.get());
        tracker.onGameTick(client, itemManager);
        assertNull(tracker.get());
        observe(12);
        APISerializable known = tracker.get();
        tracker.onGameTick(client, itemManager);
        tracker.onItemContainerChanged(container(InventoryID.BANK, new Item[0]), itemManager);
        tracker.onGameTick(client, itemManager);
        assertEquals(known, tracker.get());
    }

    @Test
    public void identicalObservationsAreEqualAndDoNotAppendItems() {
        observe(12);
        APISerializable first = tracker.get();
        observe(12);
        assertEquals(first, tracker.get());
        assertEquals(Map.of(itemId(), 12), pairs(tracker.get()));
    }

    private void observe(int quantity) {
        if (type.equals("herb_sack")) {
            if (quantity == 0) {
                chat("The herb sack is empty.");
            } else {
                chat("You look in your herb sack and see:");
                chat(quantity + " x Grimy ranarr weed");
            }
            tracker.onGameTick(client, itemManager);
        } else if (type.equals("gem_bag")) {
            chat("Sapphires: " + quantity + " / Emeralds: 0 / Rubies: 0 / Diamonds: 0 / Dragonstones: 0");
        } else {
            tracker.onItemContainerChanged(
                    container(
                            ((ContainerItems) tracker).inventoryId,
                            quantity == 0 ? new Item[0] : new Item[] {new Item(itemId(), quantity)}),
                    itemManager);
        }
    }

    private int itemId() {
        switch (type) {
            case "herb_sack":
                return ItemID.UNIDENTIFIED_RANARR;
            case "gem_bag":
                return ItemID.UNCUT_SAPPHIRE;
            case "seed_box":
                return ItemID.RANARR_SEED;
            case "chugging_barrel":
                return ItemID._1DOSE2RESTORE;
            default:
                return ItemID.COINS;
        }
    }

    private void chat(String message) {
        tracker.onChatMessage(
                client, new ChatMessage(null, ChatMessageType.GAMEMESSAGE, "", message, "", 0), itemManager);
    }

    static ItemContainer container(int identifier, Item... items) {
        ItemContainer container = mock(ItemContainer.class);
        when(container.getId()).thenReturn(identifier);
        when(container.getItems()).thenReturn(items);
        when(container.getItem(anyInt())).thenAnswer(invocation -> {
            int index = invocation.getArgument(0);
            return index < items.length ? items[index] : null;
        });
        return container;
    }

    static Map<Integer, Integer> pairs(APISerializable contents) {
        List<?> serialized = (List<?>) contents.serialize();
        Map<Integer, Integer> result = new HashMap<>();
        for (int index = 0; index < serialized.size(); index += 2) {
            result.put((Integer) serialized.get(index), (Integer) serialized.get(index + 1));
        }
        return result;
    }
}

package gimhub.items.containers;

import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.*;
import static org.mockito.Mockito.*;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import gimhub.APISerializable;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.EnumComposition;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.api.ScriptEvent;
import net.runelite.api.ScriptID;
import net.runelite.api.events.ScriptPostFired;
import net.runelite.api.events.ScriptPreFired;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.game.ItemManager;
import org.junit.Before;
import org.junit.Test;

public class StashUnitsItemsTest {
    private Client client;
    private ItemManager itemManager;
    private StashUnitsItems tracker;
    private Map<Integer, EnumComposition> enums;
    private Set<Integer> filled;
    private final int[] stack = new int[1000];

    @Before
    public void setUp() {
        client = mock(Client.class);
        itemManager = mock(ItemManager.class);
        tracker = new StashUnitsItems();
        enums = new HashMap<>();
        filled = Set.of(28958, 28959, 29019, 58602);
        JsonObject fixture = new Gson()
                .fromJson(
                        new InputStreamReader(
                                getClass().getResourceAsStream("/gimhub/stash-overview.json"), StandardCharsets.UTF_8),
                        JsonObject.class);
        for (Map.Entry<String, JsonElement> entry : fixture.entrySet()) {
            EnumComposition composition = mock(EnumComposition.class);
            JsonObject values = entry.getValue().getAsJsonObject();
            when(composition.getIntValue(anyInt())).thenAnswer(invocation -> {
                JsonElement value = values.get(Integer.toString(invocation.getArgument(0)));
                return value == null ? -1 : value.getAsInt();
            });
            when(composition.getStringValue(anyInt())).thenAnswer(invocation -> {
                JsonElement value = values.get(Integer.toString(invocation.getArgument(0)));
                return value == null ? "" : value.getAsString();
            });
            if (!entry.getKey().equals("1531")) {
                when(composition.getIntVals())
                        .thenReturn(values.entrySet().stream()
                                .mapToInt(value -> value.getValue().getAsInt())
                                .toArray());
            }
            enums.put(Integer.parseInt(entry.getKey()), composition);
        }
        when(client.getEnum(anyInt())).thenAnswer(invocation -> enums.get(invocation.getArgument(0)));
        when(client.getWidget(InterfaceID.HideyHoles.UNIVERSE)).thenReturn(mock(Widget.class));
        doReturn(PortableStorageItemsTest.container(InventoryID.HH_INV))
                .when(client)
                .getItemContainer(InventoryID.HH_INV);
        when(client.getVarps()).thenReturn(new int[5000]);
        when(client.getIntStack()).thenReturn(stack);
        when(client.getIntStackSize()).thenReturn(2);
        doAnswer(invocation -> {
                    int identifier = invocation.getArgument(1);
                    assertEquals(7, invocation.<Integer>getArgument(2).intValue());
                    assertEquals(3, invocation.<Integer>getArgument(3).intValue());
                    assertEquals(1024, invocation.<Integer>getArgument(4).intValue());
                    stack[0] = identifier == 34736 ? 0 : 1;
                    stack[1] = filled.contains(identifier) ? 1 : 0;
                    return null;
                })
                .when(client)
                .runScript(eq(ScriptID.WATSON_STASH_UNIT_CHECK), anyInt(), anyInt(), anyInt(), anyInt());
        ItemComposition composition = mock(ItemComposition.class);
        when(composition.getPlaceholderTemplateId()).thenReturn(-1);
        when(itemManager.getItemComposition(anyInt())).thenReturn(composition);
        when(itemManager.canonicalize(anyInt())).thenAnswer(invocation -> invocation.getArgument(0));
    }

    @Test
    public void overviewDiscoversPreExistingUnitsAcrossEverySectionWithoutVisitingThem() {
        open();
        assertEquals(119, snapshot().getUnits().size());
        assertEquals("filled", unit(28958).getState());
        assertEquals("filled", unit(28959).getState());
        assertEquals("unbuilt", unit(34736).getState());
        assertEquals("empty", unit(28960).getState());
        // All six section enums are read, including the final master entry beyond every visible row.
        int lastMaster = enums.get(1530).getIntVals()[24];
        verify(client).runScript(ScriptID.WATSON_STASH_UNIT_CHECK, lastMaster, 7, 3, 1024);
        verify(client, times(119))
                .runScript(eq(ScriptID.WATSON_STASH_UNIT_CHECK), anyInt(), anyInt(), anyInt(), anyInt());
        assertFalse(unit(28958).getItems().isEmpty());
    }

    @Test
    public void reopeningReconcilesFilledUnitsToEmptyAndDoesNotAppendDuplicates() {
        open();
        APISerializable first = tracker.get();
        open();
        assertEquals(first, tracker.get());
        filled = Set.of(28959);
        open();
        assertEquals(119, snapshot().getUnits().size());
        assertEquals("empty", unit(28958).getState());
        assertTrue(unit(28958).getItems().isEmpty());
        assertEquals("filled", unit(28959).getState());
    }

    @Test
    public void missingContainerOrAnUnloadedSectionDoesNotPublishAPartialOverview() {
        open();
        APISerializable known = tracker.get();
        filled = Set.of();
        when(client.getItemContainer(InventoryID.HH_INV)).thenReturn(null);
        open();
        assertSame(known, tracker.get());
        doReturn(PortableStorageItemsTest.container(InventoryID.HH_INV))
                .when(client)
                .getItemContainer(InventoryID.HH_INV);
        EnumComposition master = enums.remove(1530);
        tracker.onGameTick(client, itemManager);
        assertSame(known, tracker.get());
        enums.put(1530, master);
        tracker.onGameTick(client, itemManager);
        assertEquals("empty", unit(28958).getState());
        assertEquals(119, snapshot().getUnits().size());
    }

    @Test
    public void initializationMustCompleteBeforeCommittingTheSnapshot() {
        open();
        APISerializable known = tracker.get();
        filled = Set.of();
        pre(new Object[] {1475, 7, 3, 1024});
        tracker.onGameTick(client, itemManager);
        assertSame(known, tracker.get());
        tracker.onScriptPostFired(client, new ScriptPostFired(1475));
        tracker.onGameTick(client, itemManager);
        assertEquals("empty", unit(28958).getState());
        pre(new Object[] {1475, 7});
        tracker.onScriptPostFired(client, new ScriptPostFired(1475));
        tracker.onGameTick(client, itemManager);
        assertEquals(119, snapshot().getUnits().size());
    }

    @Test
    public void ambiguousRequirementsDoNotInventVariantsOrCountAllAlternatives() {
        open();
        assertTrue(unit(29019).getItems().isEmpty());
        assertEquals(
                List.of("Any stole", "Any heraldic rune shield"), unit(29019).getAlternatives());
        Item[] items = new Item[11];
        items[9] = new Item(ItemID.TRAIL_ZAMORAK_SCARF, 1);
        items[10] = new Item(ItemID.RUNE_HERALDIC_KITESHIELD3, 1);
        doReturn(PortableStorageItemsTest.container(InventoryID.HH_INV, items))
                .when(client)
                .getItemContainer(InventoryID.HH_INV);
        open();
        assertEquals(4, unit(29019).getItems().size());
        assertTrue(unit(29019).getItems().contains(ItemID.TRAIL_ZAMORAK_SCARF));
        assertFalse(unit(29019).getItems().contains(ItemID.TRAIL_GUTHIX_SCARF));
        assertTrue(unit(29019).getAlternatives().isEmpty());
    }

    @Test
    public void aNewAccountStartsUnknownInsteadOfReusingThePreviousOverview() {
        open();
        StashUnitsItems otherAccount = new StashUnitsItems();
        when(client.getWidget(InterfaceID.HideyHoles.UNIVERSE)).thenReturn(null);
        otherAccount.onGameTick(client, itemManager);
        assertNull(otherAccount.get());
        assertNotNull(tracker.get());
    }

    @Test
    public void enablingWithAnAlreadyOpenOverviewReadsItsCompleteListenerState() {
        when(client.getWidget(InterfaceID.HideyHoles.UNIVERSE).getOnVarTransmitListener())
                .thenReturn(new Object[] {1476, 7, 3, 1024});
        tracker.onGameTick(client, itemManager);
        assertEquals(119, snapshot().getUnits().size());
        assertEquals("filled", unit(28958).getState());
        assertEquals("filled", unit(28959).getState());
    }

    @Test
    public void wellOfVoyagePublishesAllUnitsWithItsReservedSlotEmpty() {
        for (int staff : new int[] {ItemID.IBANSTAFF, ItemID.IBANSTAFF_UPGRADED}) {
            open();
            APISerializable known = tracker.get();
            filled = Set.of(29043);
            Item[] items = new Item[51];
            items[47] = new Item(staff, 1);
            items[48] = new Item(ItemID.MYSTIC_ROBE_TOP_DARK, 1);
            doReturn(PortableStorageItemsTest.container(InventoryID.HH_INV, items))
                    .when(client)
                    .getItemContainer(InventoryID.HH_INV);
            open();
            assertSame(known, tracker.get());

            items[49] = new Item(ItemID.MYSTIC_ROBE_BOTTOM_DARK, 1);
            items[50] = new Item(-1, 0);
            tracker.onGameTick(client, itemManager);
            assertEquals(119, snapshot().getUnits().size());
            assertEquals("filled", unit(29043).getState());
            assertEquals(6, unit(29043).getItems().size());
            assertTrue(unit(29043)
                    .getItems()
                    .containsAll(List.of(staff, ItemID.MYSTIC_ROBE_TOP_DARK, ItemID.MYSTIC_ROBE_BOTTOM_DARK)));
            assertTrue(unit(29043).getAlternatives().isEmpty());
            assertEquals("empty", unit(28958).getState());
        }
    }

    @Test
    public void partiallyTransmittedExactContentsPreserveTheWholeKnownOverview() {
        open();
        APISerializable known = tracker.get();
        Item[] items = new Item[11];
        items[9] = new Item(ItemID.TRAIL_ZAMORAK_SCARF, 1);
        doReturn(PortableStorageItemsTest.container(InventoryID.HH_INV, items))
                .when(client)
                .getItemContainer(InventoryID.HH_INV);
        open();
        assertSame(known, tracker.get());
        items[10] = new Item(ItemID.RUNE_HERALDIC_KITESHIELD3, 1);
        tracker.onGameTick(client, itemManager);
        assertEquals(4, unit(29019).getItems().size());
    }

    private void open() {
        pre(new Object[] {1475, 7, 3, 1024});
        tracker.onScriptPostFired(client, new ScriptPostFired(1475));
        tracker.onGameTick(client, itemManager);
    }

    private void pre(Object[] arguments) {
        ScriptEvent event = mock(ScriptEvent.class);
        when(event.getArguments()).thenReturn(arguments);
        ScriptPreFired pre = new ScriptPreFired(1475);
        pre.setScriptEvent(event);
        tracker.onScriptPreFired(client, pre);
    }

    private StashUnitsItems.Snapshot snapshot() {
        return (StashUnitsItems.Snapshot) tracker.get();
    }

    private StashUnitsItems.Unit unit(int identifier) {
        return snapshot().getUnits().stream()
                .filter(unit -> unit.getId() == identifier)
                .findFirst()
                .orElseThrow();
    }
}

package gimhub.items.containers;

import static gimhub.items.containers.PortableStorageItemsTest.container;
import static gimhub.items.containers.PortableStorageItemsTest.pairs;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.anyInt;
import static org.mockito.Mockito.*;

import gimhub.APISerializable;
import gimhub.items.ItemRepository;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.runelite.api.*;
import net.runelite.api.events.*;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.game.ItemManager;
import org.junit.Before;
import org.junit.Test;

public class StorageEventsTest {
    private Client client;
    private ItemManager itemManager;

    @Before
    public void setUp() {
        client = mock(Client.class);
        itemManager = mock(ItemManager.class);
        ItemComposition composition = mock(ItemComposition.class);
        when(composition.getPlaceholderTemplateId()).thenReturn(-1);
        when(itemManager.getItemComposition(anyInt())).thenReturn(composition);
        when(itemManager.canonicalize(anyInt())).thenAnswer(invocation -> invocation.getArgument(0));
    }

    @Test
    public void enablingEmptyOnDeathDoesNotMakeUnknownHerbsEmpty() {
        HerbSackItems herbs = new HerbSackItems(new BankItems());
        when(client.getVarbitValue(VarbitID.EMPTYONDEATH_HERBSACK)).thenReturn(1);
        herbs.onVarbitChanged(client, -1, VarbitID.EMPTYONDEATH_HERBSACK, itemManager);
        assertNull(herbs.get());
    }

    @Test
    public void togglingEmptyOnDeathPreservesKnownHerbs() {
        HerbSackItems herbs = new HerbSackItems(new BankItems());
        chat(herbs, "You look in your herb sack and see:");
        chat(herbs, "12 x Grimy ranarr weed");
        herbs.onGameTick(client, itemManager);
        for (int preference : new int[] {1, 0}) {
            when(client.getVarbitValue(VarbitID.EMPTYONDEATH_HERBSACK)).thenReturn(preference);
            herbs.onVarbitChanged(client, -1, VarbitID.EMPTYONDEATH_HERBSACK, itemManager);
            assertEquals(Map.of(ItemID.UNIDENTIFIED_RANARR, 12), pairs(herbs.get()));
        }
        chat(herbs, "The herb sack is empty.");
        assertEquals(Map.of(), pairs(herbs.get()));
    }

    @Test
    public void emptyingIndividualHerbSacksAtDepositBoxesCreditsTheBankOnce() {
        when(client.getEnum(EnumID.RUNEPOUCH_RUNE)).thenReturn(mock(EnumComposition.class));
        when(client.getVarbitValue(VarbitID.FARMING_TOOLS_WATERINGCAN)).thenReturn(-1);
        for (int variant : new int[] {
            ItemID.SLAYER_HERB_SACK,
            ItemID.SLAYER_HERB_SACK_OPEN,
            ItemID.SLAYER_HERB_SACK_SILK,
            ItemID.SLAYER_HERB_SACK_SILK_OPEN
        }) {
            for (boolean bankKnown : new boolean[] {false, true}) {
                ItemRepository repository = new ItemRepository();
                if (bankKnown) {
                    repository.onItemContainerChanged(
                            container(InventoryID.BANK, new Item(ItemID.UNIDENTIFIED_RANARR, 5)), itemManager);
                }
                doReturn(container(InventoryID.INV, new Item(variant, 1)))
                        .when(client)
                        .getItemContainer(InventoryID.INV);
                repository.onChatMessage(
                        client,
                        new ChatMessage(
                                null, ChatMessageType.GAMEMESSAGE, "", "You look in your herb sack and see:", "", 0),
                        itemManager);
                repository.onChatMessage(
                        client,
                        new ChatMessage(null, ChatMessageType.GAMEMESSAGE, "", "12 x Grimy ranarr weed", "", 0),
                        itemManager);
                repository.onGameTick(client, itemManager);
                Map<String, APISerializable> before = new HashMap<>();
                repository.flatten(before);

                MenuEntry entry = mock(MenuEntry.class);
                when(entry.getItemId()).thenReturn(variant);
                when(entry.getOption()).thenReturn("Empty");
                when(entry.getParam1()).thenReturn(InterfaceID.BankDepositbox.INVENTORY);
                repository.onMenuOptionClicked(client, new MenuOptionClicked(entry), itemManager);
                for (int tick = 1; tick <= 4; tick++) {
                    when(client.getTickCount()).thenReturn(tick);
                    repository.onGameTick(client, itemManager);
                }
                Map<String, APISerializable> after = new HashMap<>();
                repository.flatten(after);
                assertEquals(Map.of(), pairs(after.get("herb_sack")));
                assertEquals(
                        Map.of(ItemID.UNIDENTIFIED_RANARR, bankKnown ? 17 : 12),
                        pairs(after.get(bankKnown ? "bank" : "bank_partial")));
                assertEquals(Map.of(ItemID.UNIDENTIFIED_RANARR, 12), pairs(before.get("herb_sack")));
                if (bankKnown) {
                    assertEquals(Map.of(ItemID.UNIDENTIFIED_RANARR, 5), pairs(before.get("bank")));
                }
                repository.onMenuOptionClicked(client, new MenuOptionClicked(entry), itemManager);
                repository.flatten(after);
                assertEquals(
                        Map.of(ItemID.UNIDENTIFIED_RANARR, bankKnown ? 17 : 12),
                        pairs(after.get(bankKnown ? "bank" : "bank_partial")));
            }
        }
    }

    @Test
    public void emptyingHerbsIntoInventoryOnlyRemovesTheTransferredQuantity() {
        HerbSackItems herbs = new HerbSackItems(new BankItems());
        chat(herbs, "You look in your herb sack and see:");
        chat(herbs, "12 x Grimy ranarr weed");
        herbs.onGameTick(client, itemManager);
        doReturn(container(InventoryID.INV, new Item(ItemID.SLAYER_HERB_SACK, 1)))
                .when(client)
                .getItemContainer(InventoryID.INV);
        MenuEntry entry = mock(MenuEntry.class);
        when(entry.getItemId()).thenReturn(ItemID.SLAYER_HERB_SACK);
        when(entry.getOption()).thenReturn("Empty");
        when(entry.getParam1()).thenReturn(InterfaceID.Inventory.ITEMS);
        herbs.onMenuOptionClicked(client, new MenuOptionClicked(entry), itemManager);
        herbs.onGameTick(client, itemManager);
        assertEquals(Map.of(ItemID.UNIDENTIFIED_RANARR, 12), pairs(herbs.get()));
        doReturn(container(
                        InventoryID.INV, new Item(ItemID.SLAYER_HERB_SACK, 1), new Item(ItemID.UNIDENTIFIED_RANARR, 5)))
                .when(client)
                .getItemContainer(InventoryID.INV);
        herbs.onGameTick(client, itemManager);
        assertEquals(Map.of(ItemID.UNIDENTIFIED_RANARR, 7), pairs(herbs.get()));
    }

    @Test
    public void incompleteHerbChecksPreserveThePreviousSnapshot() {
        HerbSackItems herbs = new HerbSackItems(new BankItems());
        chat(herbs, "You look in your herb sack and see:");
        chat(herbs, "2 x Grimy huasca");
        herbs.onGameTick(client, itemManager);
        APISerializable known = herbs.get();
        chat(herbs, "You look in your herb sack and see:");
        herbs.onGameTick(client, itemManager);
        assertSame(known, herbs.get());
        chat(herbs, "You look in your herb sack and see:");
        chat(herbs, "1 x Grimy ranarr weed");
        chat(herbs, "2 x Grimy unknown herb");
        herbs.onGameTick(client, itemManager);
        assertSame(known, herbs.get());
    }

    @Test
    public void allHerbSackVariantsUpdateTheSameKnownInventoryAfterConfirmedTransfers() {
        for (int variant : new int[] {
            ItemID.SLAYER_HERB_SACK,
            ItemID.SLAYER_HERB_SACK_OPEN,
            ItemID.SLAYER_HERB_SACK_SILK,
            ItemID.SLAYER_HERB_SACK_SILK_OPEN
        }) {
            HerbSackItems herbs = new HerbSackItems(new BankItems());
            chat(herbs, "The herb sack is empty.");
            doReturn(container(InventoryID.INV, new Item(variant, 1), new Item(ItemID.UNIDENTIFIED_RANARR, 4)))
                    .when(client)
                    .getItemContainer(InventoryID.INV);
            MenuEntry entry = mock(MenuEntry.class);
            when(entry.getItemId()).thenReturn(variant);
            when(entry.getOption()).thenReturn("Fill");
            MenuOptionClicked fill = new MenuOptionClicked(entry);
            herbs.onMenuOptionClicked(client, fill, itemManager);
            herbs.onGameTick(client, itemManager);
            assertEquals(Map.of(), pairs(herbs.get()));
            doReturn(container(InventoryID.INV, new Item(variant, 1)))
                    .when(client)
                    .getItemContainer(InventoryID.INV);
            herbs.onGameTick(client, itemManager);
            assertEquals(Map.of(ItemID.UNIDENTIFIED_RANARR, 4), pairs(herbs.get()));
            assertEquals(
                    Map.of(ItemID.UNIDENTIFIED_RANARR, 4),
                    herbs.onDepositContainers(client, itemManager, Set.of(variant)));
            assertEquals(Map.of(ItemID.UNIDENTIFIED_RANARR, 4), pairs(herbs.get()));
            chat(herbs, "You empty all of your containers into the bank.");
            assertEquals(Map.of(), pairs(herbs.get()));
        }
    }

    @Test
    public void seedMessagesUpdateClosedBoxesWithoutDoubleCountingContainerTransmissions() {
        SeedBoxItems seeds = new SeedBoxItems();
        seeds.onItemContainerChanged(container(InventoryID.SEED_BOX, new Item(ItemID.RANARR_SEED, 10)), itemManager);
        seeds.onGameTick(client, itemManager);
        chat(seeds, "You put 3 x Ranarr seed straight into your open seed box.");
